prompt --application/shared_components/plugins/item_type/com_hardlikesoftware_custom_popup
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(9845611008084535561)
,p_plugin_type=>'ITEM TYPE'
,p_name=>'COM.HARDLIKESOFTWARE.CUSTOM_POPUP'
,p_display_name=>'Custom Popup'
,p_supported_component_types=>'APEX_APPLICATION_PAGE_ITEMS:APEX_APPL_PAGE_IG_COLUMNS'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('ITEM TYPE','COM.HARDLIKESOFTWARE.CUSTOM_POPUP'),'')
,p_javascript_file_urls=>'#PLUGIN_FILES#custom_popup.js'
,p_css_file_urls=>'#PLUGIN_FILES#custom_popup.css'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'--===============================================================================',
'-- Renders the Custom Popup item type based on the configuration of the item.',
'--===============================================================================',
'procedure render_custom_popup (',
'    p_item in apex_plugin.t_page_item,',
'    p_plugin in apex_plugin.t_plugin,',
'    p_param in apex_plugin.t_item_render_param,',
'    p_result in out nocopy apex_plugin.t_item_render_result )',
'is',
'    c_dialog_id            constant varchar2(1000)  := p_item.attribute_01;',
'    c_editable             constant boolean  := case when p_item.attribute_02 = ''Y'' then true else false end;',
'    c_has_display_value    constant boolean  := case when p_item.attribute_02 = ''Y'' then false when p_item.attribute_03 = ''Y'' then true else false end;',
'    c_has_button           constant boolean  := case when p_item.attribute_02 = ''Y'' then true when p_item.attribute_04 = ''Y'' then true else false end;',
'    c_label                constant varchar2(400) := nvl( apex_escape.html( p_item.attribute_05 ), ''Popup Choice'' );',
'    c_display_under        constant boolean  := case when p_item.attribute_06 = ''Y'' then true else false end;',
'    c_extra_in             constant varchar2(4000)  := p_item.attribute_07;',
'    c_extra_out            constant varchar2(4000)  := p_item.attribute_08;',
'    l_escaped_value        varchar2(32767) := apex_escape.html_attribute(p_param.value);',
'    l_display_value        varchar2(32767) := l_escaped_value;',
'    l_name                 varchar2(30);',
'',
'begin',
'    apex_plugin_util.debug_page_item(p_plugin, p_item);',
'',
'    l_name := apex_plugin.get_input_name_for_item;',
'',
'    if c_has_display_value and l_escaped_value is not null then',
'        l_display_value := apex_plugin_util.get_display_data(',
'               p_sql_statement        => p_item.lov_definition,',
'               p_min_columns          => 2,',
'               p_max_columns          => 2,',
'               p_component_name       => p_item.name,',
'               p_display_column_no    => 1,',
'               p_search_column_no     => 2,',
'               p_search_string        => p_param.value,',
'               p_display_extra        => p_item.lov_display_extra);',
'    end if;',
'',
'    if p_param.is_readonly or p_param.is_printer_friendly then ',
'        apex_plugin_util.print_hidden_if_readonly (',
'            p_item_name           => l_name,',
'            p_value               => p_param.value,',
'            p_is_readonly         => p_param.is_readonly,',
'            p_is_printer_friendly => p_param.is_printer_friendly',
'        );',
'',
'        apex_plugin_util.print_display_only(',
'            p_item             => p_item,',
'            p_display_value    => l_display_value,',
'            p_show_line_breaks => false);',
'',
'    else',
'        sys.htp.prn(',
'            ''<div class="apex-item-group apex-item-group--popup-lov" role="group" aria-labelledby="'' || p_item.name || ''_LABEL">'' );',
'        -- render hidden value if there is a display value',
'        if c_has_display_value then',
'            sys.htp.prn(''<input type="hidden" name="'' || l_name || ''" '' || case when p_item.ignore_change then ''class="js-ignoreChange" '' end ||',
'                        ''id="'' || p_item.name || ''_HIDDENVALUE" value="'' || l_escaped_value || ''">'');',
'            l_name := null;',
'',
'            l_escaped_value := l_display_value;',
'',
'        end if;',
'',
'        -- render the text field widget',
'        sys.htp.prn (',
'            ''<input type="text"'' ||',
'            -- borrow some classes from native APEX popup LOV item',
'            wwv_flow_plugin_util.get_element_attributes(p_item, l_name, ''customPopupItem apex-item-text apex-item-popup-lov'', false) ||',
'            '' id="''        || p_item.name || ''"'' ||',
'            '' size="''      || p_item.element_width || ''"''||',
'            '' maxlength="'' || p_item.element_max_length || ''"'' ||',
'            case when not c_editable then '' readonly'' else '''' end ||',
'            '' value="'' || case when p_param.value is null then '''' else ltrim( rtrim ( l_escaped_value ) ) end || ''"/>'' );',
'',
'        -- and the button if needed',
'        if c_has_button then',
'            -- borrow some classes from native APEX popup LOV item',
'            sys.htp.prn (',
'                ''<button type="button" class="a-Button a-Button--popupLOV customPopupButton" id="'' || ',
'                p_item.name || ''_BTN">'' ||',
'                ''<span class="a-Icon icon-popup-lov"><span class="visuallyhidden">'' || c_label || ''</span></span></button>'');',
'        end if;',
'        sys.htp.prn( ''</div>'' );',
'    end if;',
'',
'    apex_javascript.add_onload_code (',
'        p_code => ''customPopupItemInit("''|| case when p_param.is_readonly or p_param.is_printer_friendly then p_item.name || ''_DISPLAY'' else p_item.name end ||''", {''||',
'                apex_javascript.add_attribute( ''readOnly'', p_param.is_readonly, false, true  ) ||',
'                apex_javascript.add_attribute( ''editable'', c_editable, false, true  ) ||',
'                apex_javascript.add_attribute( ''hasDisplayValue'', c_has_display_value, false, true  ) ||',
'                apex_javascript.add_attribute( ''hasButton'', c_has_button, false, true  ) ||',
'                apex_javascript.add_attribute( ''displayUnder'', c_display_under, false, true  ) ||',
'                apex_javascript.add_attribute( ''dialogId'', c_dialog_id, false, false ) ||',
'                case when c_extra_in is not null then '', extraIn: '' || c_extra_in end ||',
'                case when c_extra_out is not null then '', extraOut: '' || c_extra_out end ||',
'                ''});'' );',
'',
'    -- Tell APEX that this field is navigable',
'    p_result.is_navigable := (not p_param.is_readonly = false and not p_param.is_printer_friendly);',
'',
'end render_custom_popup;',
'',
'--===============================================================================',
'-- Return metadata for the Custom Popup item type based on the configuration of the item',
'-- for use by Interactive Grid',
'--===============================================================================',
'procedure meta_data_custom_popup (',
'    p_item in apex_plugin.t_item,',
'    p_plugin in apex_plugin.t_plugin,',
'    p_param in apex_plugin.t_item_meta_data_param,',
'    p_result in out nocopy apex_plugin.t_item_meta_data_result )',
'is',
'    c_has_display_value constant boolean := case when p_item.attribute_02 = ''Y'' then false when p_item.attribute_03 = ''Y'' then true else false end;',
'begin',
'    p_result.display_lov_definition := case when c_has_display_value then p_item.lov_definition end;',
'end meta_data_custom_popup;',
''))
