wwv_flow_imp_page.create_page(
 p_id=>6
,p_name=>'Windows List View Style'
,p_step_title=>'Windows List View Style'
,p_autocomplete_on_off=>'OFF'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.ig-windows-style .a-GV-table .a-GV-cell,',
'.ig-windows-style .a-GV-table .a-GV-controlBreakHeader {',
'    border-color: transparent;',
'}',
'.ig-windows-style .a-GV-w-frozen .a-GV-table {',
'    border-right: none;',
'}',
'.ig-windows-style .a-GV-table tr.is-hover .a-GV-cell,',
'.ig-windows-style .a-GV-table tr.is-hover.is-selected .a-GV-cell {',
'    background-color: #f2f6ff;',
'}',
'.ig-windows-style .a-GV-table tr.is-selected .a-GV-cell,',
'.ig-windows-style .a-GV-table tr.is-hover.is-selected .a-GV-cell {',
'    background-color: #dbe8ff;',
'}',
'.ig-windows-style .a-GV-hdr {',
'    background-color: #fcfcfc;',
'}',
'.a-IG-contentContainer {',
'    margin-top: 0;',
'}',
'',
'.ig-windows-style .u-selector {',
'    box-shadow: none;',
'    border: 1px transparent;',
'}',
'',
'.ig-windows-style .a-GV-hdr tr .u-selector,',
'.ig-windows-style tr.is-selected .u-selector,',
'.ig-windows-style tr.is-hover .u-selector {',
'    box-shadow: 0 1px 1px rgba(0,0,0,.05) inset;',
'    border: 1px solid #404040;',
'}',
''))
,p_page_template_options=>'#DEFAULT#'
,p_page_component_map=>'21'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(36677355340556141790)
,p_plug_name=>'Notes'
,p_region_template_options=>'#DEFAULT#:js-useLocalStorage:is-collapsed:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(35108653483362181373)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>This page demonstrates customizing the grid so that it looks and behaves more',
'like a modern Microsoft Windows list view (like in Windows File Explorer).',
'This is mostly about setting CSS styles for the grid. But also setting the ',
'columns to not stretch removing the Actions column and switching to use a ',
'context menu. The general idea is to give more of a desktop UI feel.',
'</p>',
'<p>A number of people have wanted to disable the auto stretching of',
'column widths. See <a href="https://community.oracle.com/thread/4000563" target="_blank">here</a> for an example.',
'As of release 18.1 there is a end user option (Action > Format > Stretch Column Widths)',
'to control this. The advanced option stretchColumns takes priority over the user setting',
'and this is why the end user menu option is missing for this page.',
'</p>',
'<p>Demonstrates:<br>',
'Customizing IG styles. Advanced configuration settings.',
'<br>Customizations:<br>',
'See Page attribute CSS: Inline. See IG attribute Advanced JavaScript Config.',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
