,p_enable_flashback=>true
,p_define_chart_view=>true
,p_enable_download=>true
,p_enable_mail_download=>true
,p_fixed_header=>'PAGE'
,p_show_icon_view=>false
,p_show_detail_view=>false
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function(config) {',
'    config.initActions = function(actions) {',
'        var dialogMessageTemplate = null;',
'',
'        actions.add({',
'            name: "selection-increase-salary",',
'            // Most places in this app I don''t bother to define a message that can be localized',
'            // but here I do. Note using labelKey rather than label.',
'            labelKey: "INCREASE_SAL",',
'            icon: "fa fa-usd fam-arrow-up",',
'            action: function() {',
'                var ig$ = $(actions.context);',
'                    view = ig$.interactiveGrid("getCurrentView");',
'',
'                if ( view.supports.edit ) { // make sure this is the editable view',
'                    // Demonstrate client side template processing',
'                    if ( !dialogMessageTemplate ) {',
'                        // initially the dialog contains a template; save it',
'                        dialogMessageTemplate = $("#dlgText").html();',
'                    }',
'                    // process the template with COUNT placeholder set to the number of selected records',
'                    $("#dlgText").html( apex.util.applyTemplate( dialogMessageTemplate, {',
'                        placeholders: { COUNT: ig$.interactiveGrid("getSelectedRecords").length }',
'                    } ) );',
'                    apex.theme.openRegion("increaseSalaryDialog");',
'                }',
'            }            ',
'        });',
'    }',
'    ',
'    // Typically the Actions->Selection menus is the same as the Selection Actions menu so ',
'    // want to add selection-increase-salary there also. The actions menu is generally ',
'    // updated as follows:',
'    //var toolbarData = $.apex.interactiveGrid.copyDefaultToolbar();',
'    //toolbarData.toolbarFind("selection_submenu").menu.items.push({',
'    //    type: "action",',
'    //    action: "selection-increase-salary"',
'    //});',
'    //config.toolbarData = toolbarData;',
'    // However in the case of the selection menu it is not fully populated until',
'    // all the veiws are initialized so the menu is updated when the page loads',
'    // see page execute when page loads attribute.',
'    ',
'',
'    // The grid uses traditional paging and the following option allows selecting rows on multiple pages ',
'    // compare with persistSelection commented out or set to false; then the salaray',
'    // can be increased only for rows on the current page.',
'    config.defaultGridViewOptions = {',
'        persistSelection: true',
'    };',
'    return config;',
'}'))
);
