wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(32021040653016447786)
,p_event_id=>wwv_flow_imp.id(32021040563826447785)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var message, validity, item, errors = [],',
'    input$ = $(this.triggeringElement),',
'    min = parseFloat(input$.attr("min")),',
'    max = parseFloat(input$.attr("max")),',
'    val = parseFloat(input$.val());',
'',
'/* If input type text supported min and max attributes, or if I used type number, then custom validation code would',
' * not be needed except to check if the item was valid on OK and to call show/clearErrors.',
' */',
'',
'console.log("Validate ", min, max, val);',
'if (input$.val() !== "") {',
'    // this could be more strict for example it doesn''t catch "5abc"',
'    if ( isNaN(val) || val < min || val > max ) {',
'        message = "invalid"; // doesn''t matter what the text is because data-valid-message is used',
'    } else {',
'        message = "";',
'    }',
'    input$[0].setCustomValidity(message);',
'}',
'item = apex.item(input$[0].id);',
'validity = item.getValidity();',
'if ( !validity.valid ) {',
'    errors.push( {',
'        message: item.getValidationMessage(),',
'        location: "inline",',
'        pageItem: item.id',
'    } );',
'    apex.message.showErrors( errors );',
'} else {',
'    apex.message.clearErrors( item.id );',
'}',
''))
);
