,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var val = $v("C_NOTES");',
'if (val.length >= 180) {',
'    val = val.substr(0, 180) + "...";',
'}',
'',
'// I think you should be able to set the value of a hidden column if Value Protected = No but this doesn''t work.',
'//apex.item("C_NOTES_SHORT").setValue(val);',
'// But starting in 18.2 you can at least update the model',
'// Would be nice if there were an item so simple code above would work',
'// but currently no item is rendered for hidden columns with value protected = NO',
'var view = apex.region("emp").call("getCurrentView"),',
'    model = view.model,',
'    recordId = view.getActiveRecordId(),',
'    record = model.getRecord(recordId);',
'model.setValue(record, "NOTES_SHORT", val);',
''))
);
