 p_id=>wwv_flow_imp.id(38038057896940812207)
,p_internal_uid=>10287199622055615140
,p_is_editable=>true
,p_edit_operations=>'i:u:d'
,p_lost_update_check_type=>'VALUES'
,p_add_row_if_empty=>true
,p_submit_checked_rows=>false
,p_lazy_loading=>false
,p_requires_filter=>false
,p_show_nulls_as=>'-'
,p_select_first_row=>true
,p_fixed_row_height=>true
,p_pagination_type=>'SCROLL'
,p_show_total_row_count=>true
,p_show_toolbar=>true
,p_toolbar_buttons=>'SEARCH_COLUMN:SEARCH_FIELD:ACTIONS_MENU:SEARCH_COLUMN:SEARCH_FIELD:ACTIONS_MENU:RESET:SAVE'
,p_enable_save_public_report=>false
,p_enable_subscriptions=>true
,p_enable_flashback=>true
,p_define_chart_view=>true
,p_enable_download=>true
,p_enable_mail_download=>true
,p_fixed_header=>'PAGE'
,p_show_icon_view=>false
,p_show_detail_view=>false
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function(config) {',
'    // client side updates to model highlight metadata can override user defined report',
'    // setting highlights so may want to disable that fature',
'    //apex.util.getNestedObject(config, "views.grid.features").highlight = false;',
'',
'    // Using actions is the best way to add custom functionality to an IG',
'    config.initActions = function(actions) {',
'        actions.add([',
'          {',
'            name: "selection-mark",',
'            label: "Mark", // todo use key',
'            icon: "fa fa-flag-checkered",',
'            action: function() {',
'                var i, model, records, record, id, meta,',
'                    ig$ = $(actions.context); // this is how to get the IG widget element from within initActions',
'                    view = ig$.interactiveGrid("getCurrentView");',
'',
'                // only bother if the view supports highlight (currently ony views based on grid widget do)',
'                if ( view.supports.highlight ) {',
'                    records = ig$.interactiveGrid("getSelectedRecords");',
'                    if ( records.length === 0 ) {',
'                        return;',
'                    }',
'                    model = view.model;',
'                    for ( i = 0; i < records.length; i++ ) {',
'                        record = records[i];',
'                        id = model.getRecordId(record);',
'                        meta = model.getRecordMetadata(id);',
'                        // there can only be one highlight class applied to a row',
'                        // if there is already a highlight (from the highligh dialog report settings) save it',
'                        if ( meta.highlight ) {',
'                            meta.savedHighlight = meta.highlight;',
'                        }',
'                        meta.highlight = "marked";',
'                        model.metadataChanged(id);',
'                    }',
'                    // Prior to 18.2 the grid did not respond to model highlight metadata changes; now it does so no need for refresh',
'                    // view.view$.grid("refresh");',
'                }',
'            }            ',
'          },',
'          {',
'            name: "selection-unmark",',
'            label: "Un-mark", // todo use key',
'            icon: "fa fa-flag-o",',
'            action: function() {',
'                var i, model, records, record, id, meta,',
'                    ig$ = $(actions.context);',
'                    view = ig$.interactiveGrid("getCurrentView");',
'',
'                if ( view.supports.highlight ) {',
'                    records = ig$.interactiveGrid("getSelectedRecords");',
'                    if ( records.length === 0 ) {',
'                        return;',
'                    }',
'                    model = view.model;',
'                    for ( i = 0; i < records.length; i++ ) {',
'                        record = records[i];',
'                        id = model.getRecordId(record);',
'                        meta = model.getRecordMetadata(id);',
'                        if ( meta.highlight === "marked" ) {',
'                            // if there is already a highlight save it',
'                            if ( meta.savedHighlight ) {',
'                                meta.highlight = meta.savedHighlight',
'                            } else {',
'                                delete meta.highlight;',
'                            }',
'                            model.metadataChanged(id);',
'                        }',
'                    }',
'                    // Prior to 18.2 the grid did not respond to model highlight metadata changes; now it does so no need for refresh',
'                    // view.view$.grid("refresh");',
'                }',
'            }',
'          }',
'        ]);',
'    }',
'    return config;',
'}'))
);
