prompt --application/pages/page_00014
begin
wwv_flow_imp_page.create_page(
 p_id=>14
,p_name=>'Column Help'
,p_step_title=>'Column Help'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// see IG attribute JavaScript Initialization Code and the cell focus change DA for how this global is used',
'var gEmpLastColumnDef = null;',
''))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/*',
' * there is no config option to control having a help button in the ',
' * column header menu. This hack relies on markup that could change',
' * Uncomment if desired',
'.a-IRR-sortWidget-actions-item button[data-option="help"] {',
'    display:none;',
'}',
'*/',
'',
'.extraInfo {',
'    list-style-type: none;',
'    margin: 0 10px;',
'}',
'.extraInfo h3 {',
'    font-size: 1.8rem;',
'    margin: 8px 0;',
'}',
'.extraInfo .is-active h3 {',
'    font-weight: bold;',
'}',
'.extraInfo p {',
'    display: none;',
'}',
'.extraInfo .is-active p {',
'    display: block;',
'}'))
,p_step_template=>wwv_flow_imp.id(35108644789620181358)
,p_page_template_options=>'#DEFAULT#'
,p_page_component_map=>'21'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(4195461463056735867)
,p_plug_name=>'Extra Column Info'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(35108658789039181378)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul class="extraInfo">',
'<li id="extraENAME"><h3>Name</h3>',
'<p>Extra info about the Name column.</p>',
'</li>',
'<li id="extraJOB"><h3>Job</h3>',
'<p>Extra info about the Job column.</p>',
'</li>',
'<li id="extraMGR"><h3>Manager</h3>',
'<p>Extra info about the Manager column.</p>',
'</li>',
'<li id="extraHIREDATE"><h3>Hire Date</h3>',
'<p>Extra info about the Hire Date column.</p>',
'</li>',
'<li id="extraSAL"><h3>Salary</h3>',
'<p>Extra info about the Salary column.</p>',
'</li>',
'<li id="extraCOMM"><h3>Commission</h3>',
'<p>Extra info about the Commission column.</p>',
'</li>',
'<li id="extraNOTES"><h3>Notes</h3>',
'<p>Extra info about the Notes column.</p>',
'</li>',
'',
'</ul>',
'',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(32254074935324173386)
,p_plug_name=>'Notes'
,p_region_template_options=>'#DEFAULT#:js-useLocalStorage:is-collapsed:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(35108653483362181373)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>This example adds the column help as a tooltip on the column heading.',
'This was requested in this <a target="_blank" href="https://community.oracle.com/thread/4162400">forum thread</a>.',
'A related <a target="_blank" href="https://community.oracle.com/thread/4165691">question</a> was ',
'asked about how to tell what the currently focused column is.',
'There is no API to get this information but this page includes an example of a hack to get',
'the current column from the tooltip content callback. This is useful in cases where you want',
'to keep some other part of the page in sync with the currently focused column.',
'</p>',
'<p>Customizations:<br>',
'The tooltip is defined in the Interactive Grid attribute Advanced: JavaScript Initialization Code.',
'Note: prior to 18.2 the built-in IG tooltip did not support the column headings.',
'This shows the internal details of how to request the column help from the server.',
'Similar to what apex.theme.popupFieldHelp does. The internal details could change in the future.',
'See the code for how the help text is cached to avoid getting it from the server each time.',
'See also the Dynamic Action that keeps the Extra Column Info in sync with the focused column.',
'There is some inline CSS to style and show or hide the Extra Column Info.',
'<br>Issues:<br>',
'There is no way to remove the help button from the column heading popup.',
'See the inline CSS for a hack to hide the button.<br>',
'Tooltips shouldn''t show while the column header popup is open.<br>',
'It would be nice if there were an API to get the currently focused column (or row).',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(35342233666119985669)
