'function(config) {',
'    config.defaultGridViewOptions = {',
'        tooltip: {',
'            content: function(callback, model, recordMeta, colMeta, columnDef ) {',
'                // There is no supported public API to get the column from the focused cell',
'                // this is a hack that uses the tooltip to save the columnDef for use',
'                // external to the tooltip',
'                gEmpLastColumnDef = columnDef || null;',
'',
'                if ( recordMeta === null && columnDef !== null && columnDef.helpid) {',
'                    // check if help is cached',
'                    if ( columnDef.jjs_helpTooltipText ) {',
'                        return columnDef.jjs_helpTooltipText;',
'                    }',
'                    // avoid duplicate requests',
'                    if ( columnDef.jjs_helpRequestActive ) {',
'                        return;',
'                    }',
'                    columnDef.jjs_helpRequestActive = true;',
'                    $.getJSON("wwv_flow_item_help.show_help?p_item_id=" + columnDef.helpid +',
'                              "&p_session=" +  $v( "pInstance" ) +',
'                              "&p_output_format=JSON",',
'                        function( data ) {',
'                            delete columnDef.jjs_helpRequestActive;',
'                            if ( data.title && data.helpText ) {',
'                                // Cache the tooltip so we don''t have to get it again.',
'                                // Note by caching it in the column definition object it will',
'                                // be cleared when the report changes or is reset.',
'                                // Caching in a global object would not have this drawback',
'                                columnDef.jjs_helpTooltipText = "<h3>" + data.title + "</h3><p>" + data.helpText + "</p>";',
'                                callback( columnDef.jjs_helpTooltipText );',
'                            }',
'                        } );',
'                }',
'            }',
'        }',
'    };',
'    return config;',
'}'))
);
