,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/*',
' * When the active cell changes update the extra column info to show the active column.',
' */',
'var labelledBy, extra$,',
'    cell$ = $(this.browserEvent.target).closest(".a-GV-cell");',
'',
'$(".extraInfo .is-active").removeClass("is-active"); // clear previous active item',
'if ( cell$.length && window.gEmpLastColumnDef ) {',
'    labelledBy = cell$.attr("aria-labelledby");',
'    extra$ = $("#extra" + apex.util.escapeCSS(gEmpLastColumnDef.property));',
'    if (extra$.length) {',
'        // May or may not want this extra info added to the labelled by.',
'        // This tells screen readers to annouce the extra info text. ',
'        // May want to only add this when the column changes to avoid being too verbose.',
'        cell$.attr("aria-labelledby", labelledBy + " " + extra$[0].id);',
'        extra$.addClass("is-active"); // make the item corresponding to this column active',
'    }',
'}',
''))
);
