prompt --application/pages/page_00015
begin
wwv_flow_imp_page.create_page(
 p_id=>15
,p_name=>'Double Grid'
,p_step_title=>'Double Grid'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// create a private scope where $ is set to apex.jQuery',
'(function($) {',
'    // do this after the page loads but before the IG is initialized to catch the initial events',
'    $(function() {',
'        var ignoreReportSettingsChange = false,',
'            modelViewId;',
'',
'        //',
'        // listen for view change events to find out when grid views are created ',
'        $("#people").on("interactivegridviewchange", function(event, data) {',
'            if ( data.view === "grid" && data.created ) {',
'                var opt, h,',
'                    grid2$ = $("#peopleGrid2"),',
'                    ig$ = apex.region("people").widget(),',
'                    view = ig$.interactiveGrid("getViews", "grid");',
'',
'                if ( !grid2$.length ) {',
'                    // create div for second grid',
'                    grid2$ = $("<div id=''peopleGrid2''></div>");',
'                    ig$.after(grid2$);',
'                    grid2$.wrap("<div style=''overflow: hidden;''></div>");',
'                } else {',
'                    // destroy the previous grid',
'                    grid2$.grid("destroy");',
'                    apex.widget.util.offElementResize( grid2$.parent()[0] );',
'                }',
'                h = view.view$.height();',
'                grid2$.height(h);',
'                grid2$.parent().height(h);',
'                opt = view.view$.grid("option");',
'                opt.columnSort = false;',
'                opt.resizeColumns = false;',
'                opt.reorderColumns = false;',
'                opt.activateColumnHeader = null;',
'                grid2$.grid(opt)',
'                apex.widget.util.onElementResize( grid2$.parent()[0], function() {',
'                    grid2$.grid("resize");',
'                } );',
'            }',
'        }).on("interactivegridviewmodelcreate", function(event, ui) {',
'            var model = ui.model;',
'',
'            if ( ui.viewId === "grid" ) {',
'                if (modelViewId) {',
'                    model.unSubscribe(modelViewId);',
'                }',
'                modelViewId = model.subscribe( {',
'                    onChange: function(type, change) {',
'                        if ( type === "refresh" ) {',
'                            console.log(">> model refreshed so ignore report settings change");',
'                            $("#peopleGrid2").grid("refreshColumns"); // assume columns have changed and force rerendering the whole grid',
'                            ignoreReportSettingsChange = true;',
'                        }',
'                    }',
'                } );',
'            }',
'        }).on( "interactivegridreportsettingschange interactivegridreportchange", function(event, data) {',
'            var grid2$ = $("#peopleGrid2"),',
'                ig$ = apex.region("people").widget();',
'',
'            // there is no information about what report settings have changed',
'            // both grids share the same column definitions',
'            // so refresh grid and assume columns need to be refreshed.',
'            // but if the view is already been refreshed because the model data got refreshed ',
'            // don''t refresh twice ',
'            if (!ignoreReportSettingsChange) {',
'                console.log(">> report settings changed so update grid2");',
'                grid2$.grid("refreshColumns"); // assume columns have changed and force rerendering the whole grid',
'                grid2$.grid("refresh");',
'            }',
'            ignoreReportSettingsChange = false;',
'        })',
'    });    ',
'})(apex.jQuery);',
''))
,p_page_template_options=>'#DEFAULT#'
,p_page_component_map=>'21'
);
