prompt --application/pages/page_00016
begin
wwv_flow_imp_page.create_page(
 p_id=>16
,p_name=>'Simple Control'
,p_step_title=>'Simple Control'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/*',
' * The Edit Mode checkbox has a typical binding to an action and the intention is to control',
' * the IG edit action. But this is not currently possible because the Edit Mode checkbox',
' * is outside the actions context of the IG. If the checkbox was in the IG actions context',
' * then the class="js-actionButton" data-action="edit" attributes would be all that is needed.',
' * For this to work we create a global actions context edit toggle action that controls the IG.',
' */',
'apex.actions.add({',
'    name: "edit",',
'    labelKey: "APEX.IG.EDIT",',
'    get: function() {',
'        return apex.region("emp").call("getActions").get("edit");',
'    },',
'    set: function( v ) {',
'        apex.region("emp").call("getActions").set("edit", v);',
'    }',
'});',
'/* the above is not enough to link the global edit action to the IG edit action.',
' * must also listen for edit mode changes and update the checkbox. */',
'$("#emp").on("gridmodechange", function(e, ui) {',
'    $("#edit_mode").prop("checked", ui.editMode);',
'});',
''))
,p_page_template_options=>'#DEFAULT#'
,p_page_component_map=>'21'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(33268850528153567145)
,p_plug_name=>'Controls'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(35108649110178181367)
,p_plug_display_sequence=>20
,p_plug_source=>'<input id="edit_mode" type="checkbox" class="js-actionButton" data-action="edit"> <label for="edit_mode">Edit Mode</label>'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(34819691143727951932)
,p_plug_name=>'Notes'
,p_region_template_options=>'#DEFAULT#:js-useLocalStorage:is-collapsed:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(35108653483362181373)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>This page shows a number of buttons with dynamic actions that control the IG in simple ways.',
'</p>',
'<p>See the dynamic actions associated with each button. The difference between Cancel and Refresh ',
'is that Cancel won''t warn if there are changes to the grid before refreshing it. Hiding and ',
'showing details columns could also have been done with a saved report but this',
'changes the columns directly in the grid widget and doesn''t affect the report settings at all.',
'</p>',
'<p>A button container region with normal APEX buttons is used. See <a href="f?p=&APP_ID.:20:&SESSION.">IG Cards</a> ',
'for an example of creating a custom toolbar with the toolbar widget.',
'</p>',
'<p>Demonstrates:<br>',
'Using the apex.region api.<br>',
'Invoking a built-in IG action.<br>',
'Clearing changes in the model.<br>',
'Standard DA actions.<br>',
'Calling grid widget methods.<br>',
'Customizations:<br>',
'See page attribute Execute when Page Loads for how the Edit Mode checkbox is implemented.',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(37907849874523764215)
,p_plug_name=>'Simple Control'
,p_region_name=>'emp'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(35108658789039181378)
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select EMPNO,',
'       ENAME,',
'       JOB,',
'       MGR,',
'       HIREDATE,',
'       SAL,',
'       COMM,',
'       ONLEAVE,',
'       NOTES,',
