wwv_flow_imp_page.create_page(
 p_id=>17
,p_name=>'Split Grid and Form Multi-edit'
,p_step_title=>'Split Grid and Form Multi-edit'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function($) {',
'// need to do this here rather than in Execute when Page Loads so that the handler',
'// is setup BEFORE the IG is initialized otherwise miss the first model created event',
'$(function() {',
'    var region$ = $("#emp");',
'    // the model gets released and created at various times such as when the report changes',
'    // listen for model created events so that we can subscribe to model notifications',
'    region$.on("interactivegridviewmodelcreate", function(event, ui) {',
'        var sid, item, gridInst, view,',
'            model = ui.model;',
'        console.log("view model created: ", ui);',
'        if ( ui.viewId === "grid" ) {',
'            sid = model.subscribe( {',
'                onChange: function(type, change) {',
'                    if ( type === "set" ) {',
'                        item = apex.item("P17_" + change.field);',
'                        if ( item.node ) {',
'                            view = apex.region("emp").call("getViews","grid");',
'                            // Danger: this gets acess to private methods of base class.',
'                            // todo consider exposing these methods',
'                            gridInst = view.view$.data("apex-grid");',
'                            gridInst._setColumnItemValue( item, change.record, change.field, null );',
'                        }',
'                    } else if (type === "delete" ) {',
'                        apex.region("emp").widget().trigger("interactivegridselectionchange");',
'                    }',
'                }',
'            } );',
'        }',
'    });',
'',
'});',
'',
'})(apex.jQuery);',
''))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var notesHeight = $("#notes .t-Region-header").height();',
'',
'$("#notes .t-Region-bodyWrap").css("top", notesHeight );',
''))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* make notes popover */',
'#notes {',
'    position: relative;',
'}',
'#notes .t-Region-bodyWrap {',
'    position: absolute;',
'    background-color: #ffffff;',
'    z-index: 800;',
'    top: 20px;',
'    width: 90%;',
'    margin-left: -1px;',
'    max-height: 380px;',
'    overflow: scroll;',
'}',
'#notes .t-Region-buttons, ',
'#notes .t-Region-body {',
'    border: 1px solid rgba(0, 0, 0, 0.1);',
'    border-top-width: 0;',
'    border-bottom-width: 0;',
'}',
'#notes .t-Region-buttons--bottom {',
'    border-bottom-width: 1px;',
'} ',
'',
'/* styles for multi-valued fields*/',
'.multi-marker {',
'    display: none;',
'    color: #0680e7;',
'}',
'.t-Form-fieldContainer.is-multiValued {',
'    background-color: rgba(127, 190, 242, 0.05);',
'}',
'.t-Form-fieldContainer.is-multiValued .multi-marker {',
'    display: inline;',
'}',
''))
,p_step_template=>wwv_flow_imp.id(31531218569239773933)
