,p_submit_checked_rows=>false
,p_lazy_loading=>true
,p_requires_filter=>false
,p_show_nulls_as=>'-'
,p_select_first_row=>true
,p_fixed_row_height=>true
,p_pagination_type=>'SCROLL'
,p_show_total_row_count=>true
,p_show_toolbar=>true
,p_toolbar_buttons=>'SEARCH_COLUMN:SEARCH_FIELD:ACTIONS_MENU:SAVE'
,p_enable_save_public_report=>false
,p_enable_subscriptions=>true
,p_enable_flashback=>true
,p_define_chart_view=>true
,p_enable_download=>true
,p_enable_mail_download=>true
,p_fixed_header=>'REGION'
,p_fixed_header_max_height=>400
,p_show_icon_view=>false
,p_show_detail_view=>false
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function(config) {',
'    // need save action (hence Buttons Save checked) but don''t want it in the toolbar',
'    var $ = apex.jQuery,',
'        toolbarData = $.apex.interactiveGrid.copyDefaultToolbar(),',
'        toolbarGroup = toolbarData.toolbarFind("actions2");',
'',
'    toolbarGroup.controls.pop(); // assuming save is last in this group',
'    config.toolbarData = toolbarData;',
'',
'    config.defaultGridViewOptions = {',
'        multiple: true,',
'        contextMenuId: "emp_ig_selection_actions_menu"',
'    }',
'',
'    // Single row view doesn''t make any sense so turn it off',
'    // Logically want to do this: config.views.grid.features.singleRowView = false;',
'    // but the server may not generate the views, grid, or features objects',
'    apex.util.getNestedObject(config, "views.grid.features").singleRowView = false;',
'',
'    // want to modify selection-add-row so that it focused the details',
'    config.initActions = function(actions) {',
'        var addRow = actions.lookup("selection-add-row");',
'        var originalAction = addRow.action;',
'        addRow.action = function(event,el) {',
'            originalAction(event,el);',
'            // after the grid has had a chance to change the selection',
'            setTimeout(function() {',
'                apex.item("P17_ENAME").setFocus();',
'            }, 100);',
'            return true; // because focus was set',
'        }',
'    }',
'    return config;',
'}'))
);
