wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(31530994843272256797)
,p_event_id=>wwv_flow_imp.id(31530994690927256796)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// code adapted from grid widget base class _setModelValue',
'var event = this.browserEvent;',
'var i, result, value, prevValue, validity, id, prevId, gridInst, property, columnItem,',
'    model,',
'    view = apex.region("emp").call("getCurrentView");',
'',
'columnItem = apex.item(event.target.id);',
'',
'',
'if ( !columnItem.node || !view.supports.edit ) { // make sure this is the editable view TODO shouldn''t any view that supports selection be OK?',
'    return;',
'}',
'',
'records = gP17_editableSelection;',
'',
'if ( ! records ) {',
'    return;',
'}',
'',
'property = event.target.id.replace(/^P17_/,"");',
'if ( $(columnItem.node).closest(".t-Form-fieldContainer").hasClass("is-multiValued")) {',
'    return;',
'}',
'',
'model = view.model;',
'// Danger: this gets acess to private methods of base class.',
'// todo consider exposing these methods',
'gridInst = view.view$.data("apex-grid");',
'',
'for ( i = 0; i < records.length; i++ ) {',
'    record = records[i];',
'',
'    value = columnItem.getValue();',
'    prevId = model.getRecordId( record );',
'    prevValue = model.getValue( record, property );',
'    if ( prevValue !== null && typeof prevValue === "object" && prevValue.hasOwnProperty( "v" ) ) {',
'        value = {',
'            v: value,',
'            d: columnItem.displayValueFor( value )',
'        };',
'    }',
'    result = model.setValue( record, property, value );',
'    if ( result === "DUP" ) {',
'        gridInst._setColumnItemValue( columnItem, record, property );',
'        apex.message.alert( lang.getMessage( "APEX.GV.DUP_REC_ID" ) );',
'    } else {',
'        validity = columnItem.getValidity();',
'        id = model.getRecordId( record );',
'        if ( !validity.valid ) {',
'            model.setValidity( "error", id, property, columnItem.getValidationMessage() );',
'        } else {',
'            model.setValidity( "valid", id, property );',
'        }',
'        if ( id !== prevId ) {',
'            gridInst._identityChanged( prevId, id );',
'        }',
'    }',
'}',
''))
);
