prompt --application/pages/page_00018
begin
wwv_flow_imp_page.create_page(
 p_id=>18
,p_name=>'Edit in Dialog'
,p_step_title=>'Edit in Dialog'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function($) {',
'',
'function createEmpEditDialog() {',
'    // Danger Not sure if modelColumns and specialColumns will end up being part of the public view interface',
'    var view = apex.region("emp").call("getViews", "grid"),',
'        igConfig = apex.region("emp").call("option").config,',
'        fields = $.extend(true, {}, view.modelColumns);',
'',
'    function getColumnById(id) {',
'        var name, c;',
'        for (name in fields) {',
'            if (fields.hasOwnProperty(name)) {',
'                c = fields[name];',
'                if (c.elementId === id) {',
'                    return c;',
'                }',
'            }',
'        }',
'        return null;',
'    }',
'',
'    // destroy any previous dialog if any',
'    if ( window.gEmpEditDialog$ ) {',
'        apex.region.create( "empEditDialog" );',
'        window.gEmpEditDialog$.remove();',
'    }',
'',
'    delete fields.Actions;',
'    // Control the order and layout of recordView fields',
'    ["ENAME", "DEPTNO", "MGR", "JOB", "HIREDATE", "SAL", "COMM", "ONLEAVE", "RATING", "NOTES"].forEach(function(n, i) {',
'        fields[n].seq = i * 10;',
'    });',
'    fields.SAL.fieldColSpan = 6;',
'    fields.COMM.fieldColSpan = 6;',
'    fields.DEPTNO.fieldColSpan = 6;',
'    fields.MGR.fieldColSpan = 6;',
'    fields.HIREDATE.fieldColSpan = 10;',
'    fields.RATING.fieldCssClasses = "labelBefore"; // see custom css rule for this',
'    fields.ONLEAVE.fieldCssClasses = "labelBefore";',
'',
'    // It would be nice if createModelEditDialog would automatically',
'    // disabled ok button if the model is not editable.',
'    empEditDialog$ = $.apex.recordView.createModelEditDialog( "empEditDialog", {',
'        width: 480,',
'        height: 560,',
'        title: "Employee",',
'        modelName: "editEmp",',
'        labelAlignment: "start",',
'        formCssClasses: "u-Form--labelsAbove u-Form--stretchInputs",',
'        okLabelKey: "MY_APPLY_BTN",',
'        modelOptions: {',
'            shape: "record",',
'            recordIsArray: true,',
'            editable: true,',
'            identityField: view.specialColumns.identityField,',
'            metaField: view.specialColumns.metaField,',
'            fields: fields',
'        },',
'        load: function( model ) {',
'            var i,',
'                record =  $( this ).dialog( "option", "record" ),',
'                editable = $( this ).dialog( "option", "editable" ),',
'                newRecord = [];',
'',
'            $(this).parent().find("button.ui-button--hot").toggle(editable); // hide save button if needed',
'            model.setOption("editable", editable);',
'',
'            // the dialog model and the IG model share essentially the same field config',
'            // so record can just be copied',
'            for ( i = 0; i < record.length; i++ ) {',
'                newRecord[i] = record[i];',
'            }',
'            model.setData( newRecord );',
'        },',
'        store: function( model ) {',
'            var f, field, id,',
'                record =  $( this ).dialog( "option", "record" ),',
'                newRecord = model.getRecord();',
'',
'            for ( f in fields ) {',
'                if ( fields.hasOwnProperty(f) && f !== "_meta" ) {',
'                    field = fields[f];',
'                    if ( !field.readonly && !field.virtual ) {',
'                        view.model.setValue(record, f, newRecord[fields[f].index]);',
'                        // Assume that the dialog wouldn''t allow save if any values are invalid so clear any errors',
'                        // in case there were some from add row.',
'                        id = view.model.getRecordId(record);',
'                        view.model.setValidity( "valid", id, f );',
'                    }',
'                }',
'            }',
'        }',
'    });',
'',
'    // Add a region interface to the edit dialog just for the purpose of getSessionState method',
'    // This allows column items used in the modal edit dialog to use cascading LOVs or',
'    // DA actions that execute on the server.',
'    // The currently undocumented region getSessionState method is the mechanism that is used',
'    // to pass additional information to the server that allows it to locate the',
'    // column items in server session state.',
'    apex.region.create( "empEditDialog", {',
'        type: "CreateModalEditDialog",',
'        parentRegionId: igConfig.parentRegionStaticId,',
'        refresh: function() {',
'            // do nothing',
'        },',
'        getSessionState: function( pItemsToSubmit ) {',
'            var i, column, meta,',
'                sessionState = {',
'                    beforeAsync: function() {',
'                        empEditDialog$.find(".a-RV").recordView("lockActive");',
'                    },',
'                    afterAsync: function() {',
'                        empEditDialog$.find(".a-RV").recordView("unlockActive");',
'                    }',
'                },',
'                pageItems = [],',
'                columnItems = [],',
'                record = empEditDialog$.dialog( "option", "record" );',
'',
'            // Split out column and page items from pItemsToSubmit',
'            if ( pItemsToSubmit ) {',
'                for ( i = 0; i < pItemsToSubmit.length; i++ ) {',
'                    column = getColumnById(pItemsToSubmit[i]);',
'',
'                    // if column exists it''s a column item, if not assume it''s a page item',
'                    if ( column ) {',
'                        columnItems.push({',
'                            n: column.property,',
'                            v: apex.item( pItemsToSubmit[ i ] ).getValue()',
'                        });',
'                    } else {',
'                        pageItems.push( pItemsToSubmit[ i ] );',
'                    }',
'                }',
'            }',
'',
'            // If there are no column items, just return the page items',
'            sessionState.pageItems = pageItems;',
'',
'            if ( columnItems.length ) {',
'                // If there are column items, get the active record metadata and return pageItems and the region data',
'                meta = view.model.getRecordMetadata( view.model.getRecordId(record) );',
'                sessionState.region = {',
'                    id: igConfig.regionId,',
'                    ajaxIdentifier: igConfig.ajaxIdentifier,',
'                    ajaxColumns: igConfig.ajaxColumns,',
'                    //reportId: ..., // the report id should not be needed ',
'                    view: "grid", // this probably isn''t needed either but easy to hardcode',
'                    allowedOperations: igConfig.editable.allowedOperations["protected"],',
'                    setSessionState: {',
'                        values: columnItems,',
'                        "protected": meta["protected"],',
'                        salt: meta.salt',
'                    }',
'                };',
'            }',
'',
'            return sessionState;',
'        }',
'    });',
'',
'    // expose this for use by row-edit action',
'    window.gEmpEditDialog$ = empEditDialog$;',
'}',
'',
'// need to do this here rather than in Execute when Page Loads so that the handler',
'// is setup BEFORE the IG is initialized otherwise miss the first model created event',
'$(function() {',
'    var region$ = $("#emp");',
'    // the model gets released and created at various times such as when the report changes',
'    // listen for model created events so that we can create a dialog with same config as IG model',
'    region$.on("interactivegridviewmodelcreate", function(event, ui) {',
'        if ( ui.viewId === "grid" ) {',
'            createEmpEditDialog();',
'        }',
'    });',
'',
'    //',
'    // This is the general pattern for getting access to the views as they are created',
'    //',
'    region$.on("interactivegridviewchange", function(event, data) {',
'        if ( data.view === "grid" && data.created ) {',
'            var view = apex.region("emp").call("getViews", "grid");',
'',
'            // Do this here because it can''t be set through the IG widget at init time',
'            view.view$.grid("option", "allowEditMode", false);',
'        }',
'    });',
'});    ',
'',
'})(apex.jQuery);',
''))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* don''t focus the actions cell because button has focus */',
