'.u-Form-labelContainer .t-Button.t-Button--helpButton:active .a-Icon,',
'.u-Form-labelContainer .t-Button.t-Button--helpButton:focus .a-Icon,',
'.u-Form-labelContainer .t-Button.t-Button--helpButton:hover .a-Icon {',
