,p_show_toolbar=>true
,p_toolbar_buttons=>'SEARCH_COLUMN:SEARCH_FIELD:ACTIONS_MENU:SEARCH_COLUMN:SEARCH_FIELD:ACTIONS_MENU:RESET:SAVE'
,p_add_button_label=>'New Employee'
,p_enable_save_public_report=>false
,p_enable_subscriptions=>true
,p_enable_flashback=>true
,p_define_chart_view=>true
,p_enable_download=>true
,p_enable_mail_download=>true
,p_fixed_header=>'PAGE'
,p_show_icon_view=>false
,p_show_detail_view=>false
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function(config) {',
'    config.initActions = function(actions) {',
'        // change how add row works',
'        var addRow = actions.lookup("selection-add-row");',
'        var originalAddRowAction = addRow.action;',
'        var edit = actions.lookup("edit");',
'        var originalEditSet = edit.set;',
'        addRow.action = function(event,el) {',
'            var fakeRowEvent = $.Event("click"),',
'                ig$ = $(actions.context),',
'                view = ig$.interactiveGrid("getCurrentView");',
'',
'            // use original add row to add to the grid and model',
'            originalAddRowAction(event,el);',
'            // after the grid has had a chance to change the selection',
'            setTimeout(function() {',
'                // leave edit mode',
'                originalEditSet(false);',
'                // edit the row in a dialog',
'                actions.invoke("row-edit", fakeRowEvent, view.view$.grid("getSelection")[0][0]);',
'            }, 100);',
'            return true; // because focus was set',
'        }',
'',
'        actions.add([{',
'            name: "row-edit",',
'            label: "Edit",',
'            icon: "fa fa-pencil",',
'            action: function(event, el) {',
'                var records,',
'                    ig$ = $(actions.context);',
'                    view = ig$.interactiveGrid("getCurrentView");',
'',
'                if ( view.supports.edit ) { // make sure this is the editable view',
'                    records = view.getContextRecord( el );',
'                    if ( records.length > 0 ) {',
'                        gEmpEditDialog$.dialog("option", "record", records[0])',
'                            .dialog( "option", "editable", !actions.lookup("edit").disabled && view.model.allowEdit(records[0]) )',
'                            .dialog("open");',
'                    }',
'                }',
'            }            ',
'        }',
'        ]);',
'    };',
'',
'    // Remove edit button',
'    var toolbar = $.apex.interactiveGrid.copyDefaultToolbar();',
'    toolbar.toolbarRemove("edit");',
'    config.toolbarData = toolbar;',
'',
'    // Single row view doesn''t make any sense so turn it off',
'    // Logically want to do this: config.views.grid.features.singleRowView = false;',
'    // but the server may not generate the views, grid, or features objects',
'    apex.util.getNestedObject(config, "views.grid.features").singleRowView = false;',
'',
'    // This is what I want but allowEditMode gets explicitly set by IG so',
'    // have to override in interactivegridviewchange handler',
'//    config.defaultGridViewOptions = {',
'//        allowEditMode: false',
'//    };',
'    return config;',
'}'))
);
