wwv_flow_imp_page.create_page(
 p_id=>20
,p_name=>'IG Cards'
,p_step_title=>'IG Cards'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// define the toolbar actions',
'apex.actions.add([',
'    {',
'        name: "filter",',
'        label: "Filter",',
'        title: "Filter",',
'        icon: "fa fa-filter",',
'        action: function() {',
'            // use the IG to filter',
'            apex.region("people").call("getActions").invoke("show-filter-dialog");',
'        }',
'    },',
'    {',
'        name: "sort",',
'        label: "Sort",',
'        title: "Sort",',
'        icon: "fa fa-sequence",',
'        action: function() {',
'            // use the IG to filter',
'            apex.region("people").call("getActions").invoke("show-sort-dialog");',
'        }',
'    },',
'    {',
'        name: "search",',
'        label: "Search",',
'        title: "Search",',
'        icon: "fa fa-search",',
'        action: function() {',
'            // use the IG to search. See the customization to IG search action in IG Advanced JavaScript Code attribute',
'            apex.region("people").call("getActions").invoke("search");',
'        }',
'    },',
'    {',
'        name: "change-style",',
'        label: "Style",',
'        choices: [',
'            {label: "L", value: "t-Cards--featured", title: "Featured" },',
'            {label: "M", value: "t-Cards--basic", title: "Basic" },',
'            {label: "S", value: "t-Cards--compact", title: "Compact" }',
'        ],',
'        get: function() {',
'            var ret = "t-Cards--featured",',
'                cards$ = $("#people");',
'            ["t-Cards--featured", "t-Cards--basic", "t-Cards--compact"].forEach(function(f) {',
'                if (cards$.hasClass(f)) {',
'                    ret = f;',
'                }',
'            });',
'            return ret;',
'        },',
'        set: function(v) {',
'            var cards$ = $("#people")',
'            cards$.removeClass("t-Cards--featured t-Cards--basic t-Cards--compact");',
'            cards$.addClass(v);',
'        }',
'    },',
'    {',
'        name: "change-columns",',
'        label: "Style",',
'        choices: [',
'            {label: "1", value: "t-Cards--1cols", title: "1 Column" },',
'            {label: "2", value: "t-Cards--cols", title: "2 Columns" },',
'            {label: "3", value: "t-Cards--3cols", title: "3 Columns" }',
'        ],',
'        get: function() {',
'            var ret = "t-Cards--cols",',
'                cards$ = $("#people");',
'            ["t-Cards--1cols", "t-Cards--cols", "t-Cards--3cols"].forEach(function(f) {',
'                if (cards$.hasClass(f)) {',
'                    ret = f;',
'                }',
'            });',
'            return ret;',
'        },',
'        set: function(v) {',
'            var cards$ = $("#people")',
'            cards$.removeClass("t-Cards--1cols t-Cards--cols t-Cards--3cols");',
'            cards$.addClass(v);',
'        }',
'    }',
'',
']);',
'',
'// create a toolbar referencing the above actions',
'$("#cardsToolbar").toolbar({',
'    toolbarFor: "#people_ig",',
'    data: [',
'        {',
'            id: "search",',
'            groupTogether: true,',
'            controls: [',
'                {',
'                    type: "TEXT",',
'                    id: "search_field",',
'                    enterAction: "search"',
'                },',
'                {',
'                    type: "BUTTON",',
'                    action: "search",',
'                    iconOnly: true',
'                }',
'            ]',
'        },',
'        {',
'            id: "options",',
'            controls: [',
'                {',
'                    id: "sortBtn",',
'                    type: "BUTTON",',
'                    action: "sort",',
'                    iconOnly: true',
'                },',
'                {',
'                    id: "filterBtn",',
'                    type: "BUTTON",',
'                    action: "filter",',
'                    iconOnly: true',
'                },',
'                {',
'                    type: "RADIO_GROUP",',
'                    label: "Style",',
'                    action: "change-style"',
'                },',
'                {',
'                    type: "RADIO_GROUP",',
'                    label: "Columns",',
'                    action: "change-columns"',
'                }',
'            ]',
'        }',
'    ]',
'});',
'',
'// very simple "focus" behavior because the anchor is a button inside the card',
'// but still want the card to look like it is focused.',
'$("#people").on("click", function(event) {',
'    var target$ = $(event.target),',
'        card$ = target$.closest(".t-Card");',
'',
'    if ( card$.length && !target$.closest("button").length ) {',
'        card$.find("a").focus();',
'    }',
'}).on("focusin", function(event) {',
'    var target$ = $(event.target),',
'        card$ = target$.closest(".t-Card");',
'',
'    if ( card$.length ) {',
'        card$.parent().parent().find(".is-focused").removeClass("is-focused");',
'        card$.addClass("is-focused");',
'    }',
'});',
'',
'// let the user know when there are filters',
'function checkFilters() {',
'    var i, filter, filters,',
'        filterId = null,',
'        search = "",',
'        count = 0;',
'',
'    // search always applies to the first row filter and assume always not case sensitive',
'    filters = apex.region("people").call("getFilters"); // DANGER using an internal API ',
'    for (i = 0; i < filters.length; i++) {',
'        if ( !filterId && filters[i].type === "row" ) {',
'            search = filters[i].value;',
'            filterId = filters[i].id;',
'        } else {',
'            count += 1;',
'        }',
'    }',
'    $("#cardsToolbar").toolbar("findElement","filterBtn").toggleClass("is-active", count > 0);',
'    $("#cardsToolbar").toolbar("findElement","search_field").val(search);',
'',
'}',
'',
'apex.region("people").widget().on("interactivegridreportsettingschange", function() {',
'    checkFilters();',
'});',
'checkFilters();',
''))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* make the IG disappear */',
'.a-IG {',
'    background-color: transparent;',
