'.t-Body-title {',
'    background-color: #fff;',
'}',
'',
'/* fix hidden toolbar style bug */',
'.a-IG-header {',
'    border-width: 0;',
'    padding: 0;',
'}',
'',
'/* custom card styles */',
'.t-Cards {',
'    margin: 1.2rem 3.2rem;',
'}',
'.t-Card-info {',
'    margin: 12px auto 0 auto !important;',
'}',
'.cardLabel {',
'    font-weight: bold;',
'}',
'.cardValue {',
'    padding-left: 8px;',
'}',
'.cardCol {',
'    float: left;',
'    min-width: 100px;',
'    padding: 8px;',
'    width: 49%;',
'}',
'',
'.t-Cards--1cols .t-Cards-item {',
'    clear: both;',
'}',
'.t-Cards--1cols .t-Cards-item {',
'    width: 99%;',
'}',
'.t-Card.is-focused {',
'    box-shadow: 0 0 0 1px rgba(0,0,0,0.125) inset;',
'}'))
,p_step_template=>wwv_flow_imp.id(35108644789620181358)
,p_page_template_options=>'#DEFAULT#'
,p_page_component_map=>'21'
);
