'        case when TO_YR = 0 then '''' else TO_CHAR(TO_YR) end as TO_YR,',
'        LINK, CATEGORY,',
'        case when TO_YR = 0 then',
'            extract(year from sysdate) - FROM_YR',
'        else',
'            TO_YR - FROM_YR',
'        end as AGE,',
'        case CATEGORY',
'            when ''S_T'' then ''fa fa-rocket''',
'            when ''P'' then ''fa fa-university''',
'            when ''A'' then ''fa fa-paint-brush''',
'            when ''S'' then ''fa fa-bicycle''',
'            when ''B_L'' then ''fa fa-money''',
'            else ''fa fa-question''',
'        end as ICON,',
'        GENDER,',
'        case GENDER',
'            when ''M'' then ''fa fa-male''',
'            when ''F'' then ''fa fa-female''',
'            else ''fa fa-question''',
'        end as GENDER_ICON',
'    from EBA_DEMO_IG_PEOPLE',
''))
