,p_detail_view_before_rows=>'<ul class="t-Cards t-Cards--featured t-Cards--cols u-colors t-Cards--displayInitials">'
,p_detail_view_for_each_row=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<li class="t-Cards-item">',
'  <div class="t-Card">',
'    <span id="card_&ID." class="t-Card-wrap">',
'      <div class="t-Card-icon u-color"><span class="t-Icon fa &ICON."><span class="t-Card-initials" role="presentation">&INITIALS.</span></span></div>',
'      <div class="t-Card-titleWrap"><h3 class="t-Card-title">&NAME.</h3></div>',
'      <div class="t-Card-body">',
'        <div class="t-Card-desc">',
'          <div class="cardCol">',
'            <span class="&ICON. fa-2x"></span> &CATEGORY.<br>',
'            <span class="&GENDER_ICON. fa-2x"></span> &GENDER.',
'          </div>',
'          <div class="cardCol">',
'            <span class="cardLabel">Country: </span><span class="cardValue">&COUNTRY. </span><br>',
'              <span class="cardLabel">Born: </span><span class="cardValue">&FROM_YR. </span><br>',
'              <span class="cardLabel">Died: </span><span class="cardValue">&TO_YR. </span><br>',
'              <span class="cardLabel">Age: </span><span class="cardValue">&AGE. </span>',
'          </div>',
'        </div>',
'        <div class="t-Card-info">',
'            <a type="button" target="_blank" href="&LINK." class="t-Button t-Button--primary">',
'                <span class="t-Button-label">Learn More </span><span class="t-Icon t-Icon--right fa fa-external-link" aria-hidden="true"></span>',
'            </a>',
'        </div>',
'      </div>',
'    </span>',
'  </div>',
'</li>',
''))
,p_detail_view_after_rows=>'</ul>'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function(config) {',
'    if (!config.views) {',
'        config.views = {};',
'    }',
'    // there are now declarative attributes to remove chart and flashback.',
'    // don''t want the grid view',
'    config.views.grid = {',
'        disabled: true // starting in 19.1 this works',
'    };',
'    // Don''t want the report settings area. The only thing that would be in it are filters',
'    // and this example has other ways of indicateing that there are filters.',
'    // see replaced search functionality below and how the filter button is active when there are filters.',
'    config.reportSettingsArea = false;',
'',
'    config.defaultDetailViewOptions = {',
'        footer: false',
'    };',
'',
'    config.initActions = function(actions) {',
'        var searchAction = actions.lookup("search"),',
'            ig$ = $(actions.context);',
'',
'        // need to enhance search to use our own toolbar input field',
'',
'        // This undocumented extra action function lets you customize where the',
'        // search value comes from. Prior to 18.1 the value was returned. Now',
'        // it uses a callback to support async. prompting.',
'        searchAction.getSearchValue = function(callback) {',
'            var value = "";',
'',
'            value = $("#cardsToolbar").toolbar( "findElement", "search_field" ).val();',
'            callback(value);',
'        }',
'',
'        // Also want search from the toolbar to work differently!',
'        // Want new search term to REPLACE the current search term not add a new one.',
'        // DANGER this uses undocumented APIs that are marked internal do not use',
'        // this will change in the future and break this code',
'        searchAction.action = function() {',
'            searchAction.getSearchValue( function ( value ) {',
'                var i, filter, filterId, filters;',
'',
'                // search always applies to the first row filter and assume always not case sensitive',
'                filters = ig$.interactiveGrid("getFilters"); // DANGER using an internal API ',
'                for (i = 0; i < filters.length; i++) {',
'                    if (filters[i].type === "row" ) {',
'                        filterId = filters[i].id;',
'                        break;',
'                    }',
'                }',
'                if ( value ) {',
'                    filter = {',
'                        type: "row",',
'                        value: value,',
'                        isCaseSensitive: false',
'                    };',
'                    if ( filterId ) {',
'                        ig$.interactiveGrid("updateFilter", filterId, filter); // DANGER using an internal API',
'                    } else {',
'                        ig$.interactiveGrid("addFilter", filter ); // DANGER',
'                    }',
'                } else if (filterId ) {',
'                    ig$.interactiveGrid( "deleteFilter", filterId ); // DANGER',
'                } else {',
'                    // Just refresh if we have no search term',
'                    // think should this just do nothing?',
'                    ig$.interactiveGrid("refresh");',
'                }',
'            } );',
'        }',
'    };',
'',
'    return config;',
'}'))
);
