 p_id=>21
,p_name=>'Spinner'
,p_step_title=>'Spinner'
,p_autocomplete_on_off=>'OFF'
,p_javascript_file_urls=>'#JQUERYUI_DIRECTORY#ui/widgets/spinner.js'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'apex.jQuery(function() {',
'    apex.jQuery("#C_SAL,#C_COMM").spinner({});',
'});'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* The icons of the spinner buttons make the control a little too tall so make the ',
'   cells a little taller */',
'#emp .a-GV-cell {',
'    height: 34px;',
'}',
'.a-GV-cell .a-GV-columnItem input:not([type="radio"]):not([type="checkbox"]), .a-GV-cell .a-GV-columnItem select[size="1"] {',
'    height: 32px;',
'}',
'.a-GV-cell .a-GV-columnItem select[size="1"] {',
'    max-height: 32px;',
'}',
'.a-GV-cell .ui-spinner-input {',
'    margin: -1px 0 -1px -14px;',
'    padding-left: 14px !important;',
'}',
'.a-GV-cell .ui-spinner .ui-icon {',
'    left: 50%;',
'}'))
,p_page_template_options=>'#DEFAULT#'
,p_page_component_map=>'21'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(35128112819627934442)
,p_plug_name=>'Notes'
,p_region_template_options=>'#DEFAULT#:js-useLocalStorage:is-collapsed:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(35108653483362181373)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>On the forums someone <a href="https://community.oracle.com/message/14243423" target="_blank">asked</a> how to use the jQuery UI Spinner widget in IG.',
'The <b>best</b> thing to do would be to create an item plug-in. ',
'But the quick and dirty solution of initializing the Spinner on a number item ',
'works so it should work for a column item in IG as well.',
'</p>',
'<p>The Salary and Commission columns are given static IDs.',
'The JavaScript file is loaded in JavaScript File URLs.',
'The spinner is initialized in Function and Global Variable Declaration.',
'To make the spinner fit nicely in a grid cell a few inline CSS styles are added.',
'</p>',
'<p>To figure out what style changes were needed it was helpful to use the',
'grid widget debugCellEdit method so that the spiner input control didn''t disappear',
'while inspecting the styles.',
'</p>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
