wwv_flow_imp_page.create_page(
 p_id=>24
,p_name=>'Rich Text and Custom Popup'
,p_step_title=>'Rich Text and Custom Popup'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// utility functions',
'',
'function updateCompensation(source) {',
'    var factor,',
'        percent = $v("P24_COMM_PERCENT"),',
'        sal = parseFloat($v("P24_SAL")),',
'        salActual = parseFloat($v("P24_SAL_BIWEEKLY")),',
'        period = $v("P24_PAY_PERIOD");',
'',
'    if (percent.length > 0) {',
'        percent = parseFloat($v("P24_COMM_PERCENT")) / 100;',
'    } else {',
'        percent = 0;',
'    }',
'    factor = {',
'        "B": 1,',
'        "M": 26/12,',
'        "Y": 26',
'    }[period];',
'',
'    if (source === "P") {',
'        // assume sal biweekly is correct',
'        $s("P24_SAL", salActual * factor, null, true);',
'    } else if (source === "S") {',
'        // assume sal is correct',
'        $s("P24_SAL_BIWEEKLY", sal / factor, null, true);',
'    } else if (source === "I") {',
'        $s("P24_SAL", salActual * factor, null, true);',
'        $s("P24_COMM_PERCENT", Math.round((parseFloat($v("P24_COMM") || 0) / salActual) * 100), null, true);',
'        return;',
'    }',
'    $s("P24_COMM", percent === 0 ? "" : "" + Math.round(percent * parseFloat($v("P24_SAL_BIWEEKLY"))), null, true);',
'}',
''))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var selectManagerIG$ = apex.region("selectManagerIG").widget();',
'// set up some event handlers to make working with the select managers popup better',
'// use new activatecell event to make selection on double click or enter',
'// use down arrow in search field to move into the grid',
'',
'function saveMgrIG() {',
'    var rec = selectManagerIG$.interactiveGrid("getSelectedRecords")[0],',
'        model = selectManagerIG$.interactiveGrid("getCurrentView").model;',
'',
'    if ( rec ) {',
'        // save the selected value and close popup',
'        $("#managerDlg").popup("setValue", rec ? {',
'                v: model.getValue(rec, "EMPNO"),',
'                d: model.getValue(rec, "ENAME")',
'            } : null)',
'            .popup("option", "valueConfirmed", true)',
'            .popup("close");',
'    }',
'}',
'',
'selectManagerIG$.on("gridactivatecell", function(event) {',
'    var cell$ = $(event.target).closest(".a-GV-cell");',
'',
'    if ( (event.type === "keydown" && event.which !== $.ui.keyCode.ENTER) ||',
'            cell$.hasClass("a-GV-selHeader") || cell$.hasClass("has-button") ) {',
'        return;',
'    }',
'    saveMgrIG();',
'}).on("keydown", "#selectManagerIG_ig_toolbar_search_field", function(event) { // using internal knowledge of how id is generated',
'    if ( event.which === $.ui.keyCode.DOWN ) {',
'        selectManagerIG$.interactiveGrid("getCurrentView").view$.grid("focus");',
'        event.preventDefault();',
'    }',
'}).on("gridselectionchange", function(event) {',
'    // also since selecting just one manager (not multi select) close popup',
'    // on selection with the mouse click.',
'    if (event.originalEvent && event.originalEvent.type === "click") {',
'        saveMgrIG();',
'    }',
'});'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'#P24_RICH_TEXT_CONTAINER {',
'    margin: 0;',
'}',
'#P24_RICH_TEXT_CONTAINER .t-Form-inputContainer {',
'    padding: 0;',
'}',
'#managerDlg .t-ButtonRegion-buttons,',
'#notesDlg .t-ButtonRegion-buttons {',
'    padding: 8px;',
'}',
'',
''))
,p_page_template_options=>'#DEFAULT#'
,p_page_component_map=>'21'
);
