,p_event_id=>wwv_flow_imp.id(8813464033415477922)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var dialog$ = $("#notesDlg"),',
'    inst = dialog$.data("ui-dialog");',
'',
'inst.setValue = function(value) {',
'    $s("P24_RICH_TEXT", value);',
'};',
'inst.getValue = function() {',
'    var value = $v("P24_RICH_TEXT");',
'    return {',
'        v: value,',
'        d: apex.util.stripHTML(value).substr(0, 40)',
'    };',
'};',
'',
'// Do some fix ups to make rich text editor (which uses an iframe) work well in a dialog',
'// perhaps this should be built into the rich text editor item',
'var orig_allowInteraction = $.ui.dialog.prototype._allowInteraction;',
'$.ui.dialog.prototype._allowInteraction = function(event) {',
'    // address interaction issues with general iframes with the dialog',
'    if (event.target.ownerDocument != this.document[0]) {',
'        return true;',
'    }',
'    // address interaction issues with dialog window',
'    if ($(event.target).closest(".cke_dialog").length) {',
'        return true;',
'    }',
'    // address interaction issues with iframe based drop downs in IE',
'    if ($(event.target).closest(".cke").length) {',
'        return true;',
'    }',
'    return orig_allowInteraction.apply(this, arguments);',
'};',
'',
'var rt = CKEDITOR.instances.P24_RICH_TEXT;',
'',
'rt.on("key", function(event) {',
'    var index, tabStops$;',
'',
'    var key = event.data.keyCode;',
'    if (key === 27) { // escape',
'        dialog$.dialog("close");',
'        event.cancel();',
'    }',
'});',
'',
'// Make this focus event to cross the iframe boundary because IG ',
'// needs to track focus of popups to manage cell activation/deactivation.',
'rt.on("focus", function(event) {',
'    dialog$.find("iframe").trigger("focus");',
'});',
''))
);
