prompt --application/pages/page_00025
begin
wwv_flow_imp_page.create_page(
 p_id=>25
,p_name=>'Master Detail Dialog (close)'
,p_step_title=>'Master Detail Dialog (close)'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var app = {};',
'(function($, app) {',
'    // Master Detail pages currently have a problem with making validation',
'    // errors easily accessible. This is not specific to this example where the',
'    // detail is in a dialog. When there is a validation error in a detail model',
'    // the user is not directed to the detail IG that has the error.',
'    // Ideally IG would handle this automatically some how. Here is a ',
'    // work around that explicitly moves information about the changes and errors',
'    // in each of the detail IGs into the master IG record.',
'    function bubbleUpDetailStatus() {',
'        var details = apex.model.list(false,"emp_grid"), // warning: using internal knowledge of how IG names models',
'            masterModel = apex.region("dept").call("getViews", "grid").model;',
'',
'        // loop over all the detail models by id',
'        details.forEach(function(mid) {',
'            var errors, changes, meta,',
'                highlight = null,',
'                model = apex.model.get(mid),',
'                recId = model.getOption("parentRecordId");',
'',
'            if (recId) {',
'                // update the master model ERRORS and CHANGES hidden columns',
'                // and highlight metadata on the OPEN_DETAIL column',
'                // See page inline css rules for how the highlight class is used',
'                // See master model JavaScript Initialization Code for how tooltip',
'                // uses the errors and changes.',
'                errors = model.getErrors().length;',
'                // see doc for isChanged to see why we use it like this; its because of auto inserted records',
'                changes = model.isChanged() ? model.getChanges().length : 0;',
'                masterModel.setRecordValue(recId, "ERRORS", "" + errors);',
'                masterModel.setRecordValue(recId, "CHANGES", "" + changes);',
'                meta = masterModel.getRecordMetadata(recId);',
'                // Note this is the same technique for setting styles',
'                // based on data that is used in example page Cell Style Based on Data.',
'                if (errors > 0) {',
'                    highlight = "detail-errors";',
'                } else if ( changes > 0 ) {',
'                    highlight = "detail-changes";',
'                }',
'                fields = meta.fields;',
'                if (!fields) {',
'                    fields = meta.fields = {};',
'                }',
'                if (!fields.OPEN_DETAIL) {',
'                    fields.OPEN_DETAIL = {};',
'                }',
'                meta.fields.OPEN_DETAIL.highlight = highlight;',
'                masterModel.metadataChanged(recId); // this tells the view to update the style',
'            }',
'            apex.model.release(mid); // don''t forget this when using apex.model.get',
'        });',
'    }',
'',
'    app.bubbleUpDetailStatus = bubbleUpDetailStatus;',
'',
'    $(function() {',
'        // after save',
'        $("#dept").on("interactivegridsave", function() {',
'            bubbleUpDetailStatus();',
'        });',
'        // after emp dialog closes',
'        $("#emp").on("dialogclose", function() {',
'            bubbleUpDetailStatus();',
'        });',
'    });',
'',
'})(apex.jQuery, app);'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// Master detail association happens at two layers. ',
'// 1) The model layer: the detail model knows about the master model. This is needed',
'//    for proper functioning including saving changes.',
'// 2) The view layer: the detail IG listens for selection changes events on the master',
'//',
'// We want to break the view layer association so we can be in control of when the ',
'// detial IG view model changes.',
'',
'// Starting in 19.1 there is the option trackParentSelection so that we don''t have to turn off the internal event handler',
'// if there were multiple details all would be detached',
'// see open-details action for how the detail model instance is set',
'//apex.region("dept").widget().off("interactivegridselectionchange.ig");',
''))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* When the dialog contains something like an IG or a chart probably want',
