wwv_flow_imp_page.create_interactive_grid(
 p_id=>wwv_flow_imp.id(4195461756252735870)
,p_internal_uid=>299922307232480918
,p_is_editable=>true
,p_edit_operations=>'i:u:d'
,p_lost_update_check_type=>'VALUES'
,p_add_row_if_empty=>true
,p_submit_checked_rows=>false
,p_lazy_loading=>false
,p_requires_filter=>false
,p_show_nulls_as=>'-'
,p_select_first_row=>true
,p_fixed_row_height=>true
,p_pagination_type=>'SCROLL'
,p_show_total_row_count=>true
,p_show_toolbar=>true
,p_toolbar_buttons=>'SEARCH_COLUMN:SEARCH_FIELD:ACTIONS_MENU:SEARCH_COLUMN:SEARCH_FIELD:ACTIONS_MENU:RESET:SAVE'
,p_enable_save_public_report=>false
,p_enable_subscriptions=>true
,p_enable_flashback=>true
,p_define_chart_view=>true
,p_enable_download=>true
,p_enable_mail_download=>true
,p_fixed_header=>'PAGE'
,p_show_icon_view=>false
,p_show_detail_view=>false
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function(config) {',
'    config.initActions = function(actions) {',
'        ig$ = $(actions.context); // this is the detail dept IG widget',
'',
'        actions.add({',
'            name: "open-details", ',
'            label: "Open Employees", // todo use a text message',
'            action: function(event, el) {',
'                var rec, empInst, model,',
'                    view = ig$.interactiveGrid("getCurrentView");',
'',
'                // intend there is only a grid view but don''t assume',
'                if ( view.internalIdentifier === "grid" ) {',
'                    // The view layer master detail association on seleciton change has been broken with trackParentSelection',
'                    // So must manually set the correct detail model instance',
'                    model = ig$.interactiveGrid("getCurrentView").model;',
'                    // get the context row',
'                    rec = view.getContextRecord( el )[0]; // not currently documented but probably should be',
'                    apex.region("emp").call("setMasterRecord", model, rec);',
'',
'                    // set title and open dialog',
'                    $("#emp").dialog("option", "title", "Employees in " + model.getValue(rec, "DNAME")); // todo should use apex.lang.formatMessage',
'                    apex.theme.openRegion("emp"); // the new API to open a dialog region',
'                    return true; // action should not set foucs because dialog gets focus',
'                }',
'            }',
'        });',
'    };',
'    config.defaultGridViewOptions = {',
'        tooltip: {',
'            content: function(callback, model, recordMeta, colMeta, columnDef) {',
'                var errors, changes,',
'                    text = "Open Employees"; // todo use text message',
'',
'                if ( columnDef && columnDef.property === "OPEN_DETAIL" && recordMeta) {',
'                    errors = parseInt(model.getValue(recordMeta.record, "ERRORS"), 10);',
'                    changes = parseInt(model.getValue(recordMeta.record, "CHANGES"), 10);',
'                    if (changes > 0 || errors > 0) {',
'                        if ( errors ) {',
'                            text += "<br>" + errors + " Errors";',
'                        } else if ( changes ) {',
'                            text += "<br>" + changes + " Changes";',
'                        }',
'                    }',
'                    return text;',
'                }',
'            }',
'        }',
'    }',
'    return config;',
'}'))
);
