wwv_flow_imp_page.create_page(
 p_id=>26
,p_name=>'Master Detail Dialog (save)'
,p_step_title=>'Master Detail Dialog (save)'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// Master detail association happens at two layers. ',
'// 1) The model layer: the detail model knows about the master model. This is needed',
'//    for proper functioning including saving changes.',
'// 2) The view layer: the detail IG listens for selection changes events on the master',
'//',
'// We want to break the view layer association so we can be in control of when the ',
'// detial IG view model changes.',
'',
'// Starting in 19.1 there is the option trackParentSelection so that we don''t have to turn off the internal event handler',
'// if there were multiple details all would be detached',
'// see open-details action for how the detail model instance is set',
'//apex.region("dept").widget().off("interactivegridselectionchange.ig");',
''))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* When the dialog contains something like an IG or a chart probably want',
' * it to fill the whole dialog without padding. There should be a template ',
' * option for this but currently there isn''t so add this rule and add',
' * dialog-no-pad to the dialog region CSS classes.',
' * Starting in 19.1 can use the Remove Body Padding option',
'.dialog-no-pad .t-DialogRegion-body {',
'    padding: 0;',
'}',
unistr('/* If you don\2019t like so much space around the buttons add this rule as well'),
' */',
'.dialog-no-pad .t-ButtonRegion-buttons {',
'    padding: 8px;',
'}',
'/* Optional if you don''t like a border around the IG when it is in a dialog',
' * See resize DA for impact this has on height calculation.',
' */',
'.dialog-no-pad .a-IG {',
'    border-width: 0;',
'}',
''))
,p_page_template_options=>'#DEFAULT#'
,p_page_component_map=>'21'
);
