wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(4209204159377300401)
,p_event_id=>wwv_flow_imp.id(4209203661970300401)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// This is the use case where the any edits to the detail region must be saved or discarded before leaving the dialog.',
'// This use case has the advantage of forcing the user to deal with any validation errors before moving on.',
'var emp$ = apex.region("emp").widget();',
'var view = emp$.interactiveGrid("getCurrentView");',
'var model = view.model;',
'if ( !model.isChanged() ) {',
'    // no changes so just close',
'    apex.theme.closeRegion( "emp" );',
'} else {',
'    // else save will actually do something',
'    emp$.interactiveGrid("getActions").invoke("save");',
'    // if save happens need to wait for it to complete and only close the dialog if there are no errors.',
'    emp$.on("interactivegridsave", function(event, ui) {',
'        emp$.off("interactivegridsave");',
'        if ( ui.status === "success" ) {',
'            apex.theme.closeRegion( "emp" );',
'        } // else the dialog doesn''t close.',
'    });',
'}'))
);
wwv_flow_imp_page.create_page_da_event(
 p_id=>wwv_flow_imp.id(4209204598907300401)
,p_name=>'cancel emp details'
,p_event_sequence=>50
,p_triggering_element_type=>'BUTTON'
,p_triggering_button_id=>wwv_flow_imp.id(4209194915552300370)
