,p_action=>'NATIVE_CLOSE_REGION'
,p_affected_elements_type=>'REGION'
,p_affected_region_id=>wwv_flow_imp.id(35736258530816860216)
,p_da_action_comment=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Just close the dialog. The close handler will',
'take care of canceling any edits'))
);
wwv_flow_imp_page.create_page_da_event(
 p_id=>wwv_flow_imp.id(4209205480928300402)
,p_name=>'cancel edits'
,p_event_sequence=>60
,p_triggering_element_type=>'REGION'
,p_triggering_region_id=>wwv_flow_imp.id(35736258530816860216)
,p_bind_type=>'bind'
,p_execution_type=>'IMMEDIATE'
,p_bind_event_type=>'custom'
,p_bind_event_type_custom=>'dialogbeforeclose'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(4209206030633300405)
,p_event_id=>wwv_flow_imp.id(4209205480928300402)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// This DA is intended to be used with the case where the details dialog either saves',
'// changes or canceles any changes.',
'// The logic goes in the beforeclose event so it catches both the (X) in the header',
'// and the cancel button and can prevent the close if needed.',
'var emp$ = apex.region("emp").widget();',
'var view = emp$.interactiveGrid("getCurrentView");',
'var model = view.model;',
'if ( model.isChanged() ) {',
'    this.browserEvent.preventDefault(); // abort close until after confirm',
'    apex.message.confirm("You have made changes. Do you want to close and loose changes?", function(ok) { // todo use a text message',
'        if ( ok ) {',
'            // leave edit mode so that the column items will be reinitialized',
'            emp$.interactiveGrid("getActions").set("edit", false);',
'            model.clearChanges();',
'            apex.theme.closeRegion( "emp" );',
'            apex.region("emp").refresh(); // do this after it closes',
'        }',
'    });',
'}',
'// else no changes just let close happen'))
);
