prompt --application/pages/page_00029
begin
wwv_flow_imp_page.create_page(
 p_id=>29
,p_name=>'Tabbed Record Editing'
,p_step_title=>'Tabbed Record Editing'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// this should go in a file',
'var app = {};',
'(function($, app) {',
'',
'    // Assumes it is just the grid view model to be detached. The IG shouldn''t have any other views.',
'    // while detached don''t do anything to the view that would cause it to recreate the models',
'    function detachModel(igRegionId) {',
'        var view = apex.region(igRegionId).call("getCurrentView");',
'',
'        if (view.view$) {',
'            view.view$.grid( "option", "modelName", null );',
'        }',
'        if (view.singleRowView$ && view.singleRowView$.length > 0) {',
'            view.singleRowView$.recordView( "option", "modelName", null );',
'        }',
'        return view.model;',
'    }',
'    app.detachModel = detachModel;',
'',
'    // Assumes it is just the grid view model to be attached. The IG shouldn''t have any other views.',
'    function attachModel(igRegionId) {',
'        var view = apex.region(igRegionId).call("getCurrentView");',
'        if (view.view$) {',
'            view.view$.grid( "option", "modelName", view.modelName );',
'        }',
'        if (view.singleRowView$ && view.singleRowView$.length > 0) {',
'            view.singleRowView$.recordView( "option", "modelName", view.modelName );',
'        }',
'    }',
'    app.attachModel = attachModel;',
'',
'    // To use an IG just for its model:    ',
'    // Create an IG editable or not with simple template id and attributes no grid and custom attributes: style="display:none;".',
'    // also heading fixed to region. May want to set lazy load to have full control over the data that is fetched.',
'    // then call this function.',
'    app.useHiddenIGasModel = function(igRegionId) {',
'        return detachModel(igRegionId);',
'    }',
'    // Use this function in the IG JS Init Code.',
'    // For a hidden IG strip out as much as possible',
'    // Some of this can be done declarativly but this does it all in one place',
'    app.hiddenInitIG = function(config) {',
'        var feat = apex.util.getNestedObject(config, "features");',
'        // global features',
'        feat.filter = false;',
'        feat.flashback = false;',
'        feat.download = false;',
'        // grid features',
'        feat = apex.util.getNestedObject(config, "views.grid.features");',
'        feat.singleRowView = false;',
'        feat.aggregate = false;',
'        feat.controlBreak = false;',
'        feat.highlight = false;',
'        apex.util.getNestedObject(config, "views.chart").disabled = true;',
'        return config;',
'    };',
'',
'    // This tricks the model into fetching a specific record by id',
'    app.fetchRecord = function(model, id) {',
'        var rec, newId, meta,',
'            idField = model.getOption("identityField")[0]; // assume single primary key',
'',
'        rec = model.getRecord(id);',
'        if (!rec) {',
'            // can''t fetch a record that isn''t in the model so insert one',
'            newId = model.insertNewRecord();',
'            rec = model.getRecord(newId);',
'            meta = model.getRecordMetadata(newId);',
'            model.setValue(rec, idField, id); // change the id',
'            meta.inserted = false; // and lie about it ever being inserted',
'            delete meta.originalId;',
'        }',
'        return model.fetchRecords([rec]);',
'    };',
'',
'    app.simpleBinding = function(model, recId, form$) {',
'        form$.find("[data-bind]").each(function() {',
'            var val,',
'                rec = model.getRecord(recId),',
'                el$ = $(this),',
'                field = el$.attr("data-bind");',
'            val = model.getValue(rec, field);',
'            if (val === null) {',
'                val = "";',
'            } else if (typeof val === "object" && val.hasOwnProperty("v")) {',
'                val = val.v;',
'            }',
'            el$.val(val);',
'        }).on("change", function(event) {',
'            var el$ = $(event.target),',
'                field = el$.attr("data-bind"),',
'                val = el$.val(),',
'                curRecId = el$.closest(".ui-tabs-panel").attr("data-name"),',
'                rec = model.getRecord(curRecId),',
'                modelVal = model.getValue(rec, field);',
'',
'            if (typeof modelVal === "object" && modelVal.hasOwnProperty("v")) {',
'                val = {v:val, d:""};',
'            }',
'            model.setValue(rec, field, val);',
'            // if it is changed assume it is now valid',
'            model.setValidity( "valid", curRecId, field );',
'            // todo support client side validation',
'        });',
'    };',
'',
'    // for tab template to make ids unique',
'    app.gIdCounter = 1;',
'',
'$(function() {',
'// resize logic to fit page to window',
'// see page Wide Report for more on how resizing to fit the page works',
'function resizeMainContent() {',
'    var tabs$ = $("#tabs"),',
'        height = $(window).height(); // start with the window height',
'    height -= $(".t-Header").outerHeight();',
'    height -= $("#t_Body_content_offset").height();',
'    height -= $("#controlBar").outerHeight();',
'    height -= $(".t-Footer").outerHeight();',
'    apex.util.setOuterHeight(tabs$, height - 1); // -1 to fix rounding sometimes',
'    if (tabs$.hasClass("ui-tabs")) {',
'        tabs$.tabs("refresh"); // tabs want to be refreshed after size changes',
'    }',
'}',
'$(window).on("apexwindowresized", resizeMainContent);',
'resizeMainContent();',
'',
'// extend tabs widget to support add/remove tabs',
'$.widget("ui.tabs", $.ui.tabs, {',
'    _create: function() {',
'        var header$,',
'            tabs$ = this.element,',
'            self = this;',
'        this.tabId = 10;',
'        this.tabsPrefix = (this.element.prop("id") || "tabs") + "-";',
'        this._super();',
'',
'        header$ = tabs$.find(".ui-tabs-nav").sortable({',
'            axis: "x",',
'            stop: function() {',
'                tabs$.tabs( "refresh" );',
'            }',
'        });',
'        // (undocumented API) add touch support to the sortable',
'        apex.widget.util.TouchProxy.addTouchListeners(header$[0]);',
'',
'        tabs$.on( "click", ".remove-tab", function(event) {',
'            var id = $(this).closest("li").attr("aria-controls");',
'            self.remove(id, event);',
'        });',
'        tabs$.on( "keyup", function(event) {',
'            if ( event.altKey && event.keyCode === $.ui.keyCode.BACKSPACE ) {',
'                var id = tabs$.find(".ui-tabs-active").attr("aria-controls");',
'                self.remove(id, event);',
'            }',
'        });',
'    },',
'    add: function(options, event) {',
'        var tabs$ = this.element,',
'            id = this.tabsPrefix + this.tabId,',
'            index = tabs$.find(".ui-tabs-tab").length, // will be index of new tab',
'            li = "<li><a href=''#" + id + "''>" + options.title + "</a>";',
'',
'        if (options.removable) {',
'            li += " <span class=''remove-tab fa fa-times-circle-o'' role=''presentation''><span class=''u-vh''>Remove Tab</span></span>"; // todo use text message',
'        }',
'        li += "</li>";',
'        li = $(li);',
'        tabs$.find(".ui-tabs-nav").append(li);',
'        tabs$.append("<div id=''" + id + "''>" + options.content + "</div>");',
'        this.refresh();',
'        if (options.makeActive) {',
'            tabs$.tabs("option", "active", index);',
'        }',
'        this._trigger("add", event || null, {',
'            id: id',
'        });',
'        this.tabId++;',
'        return id;',
'    },',
'    remove: function(id, event) {',
'        var tabs$ = this.element;',
'        this._trigger("remove", event || null, {',
'            id: id',
'        });',
'        if (event && event.isDefaultPrevented()) {',
'            return;',
'        } // else',
'        tabs$.find("[aria-controls=''" + id +"'']").remove();',
'        tabs$.find("#" + id).remove();',
'        this.refresh();',
'    }',
'});',
'$("#tabs").on("tabscreate", function() {',
'    // Would be better if the jQuery tabs template had a template option for heightStyle',
'    // set this as soon as it is created.',
'    $("#tabs").tabs("option", "heightStyle", "fill");',
'    setTimeout(function() {',
'        // an extra refresh is needed to pick up the initial height',
'        $("#tabs").tabs("refresh"); // tabs want to be refreshed after size changes',
'    }, 1);',
'});',
'',
'});',
'',
'})(apex.jQuery, app);',
''))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// Use the emp IG model, Make it available to DAs etc.',
'var model = app.gEmpModel = app.useHiddenIGasModel("emp");',
'var gShowingSuccess = false;',
'// add model observer. don''t care about viewid because never going to unsubscribe',
'model.subscribe({',
'    onChange: function(changeType, change) {',
'        var i, id, newId,',
'            tabs$ = $("#tabs");',
'        if (gShowingSuccess) {',
'            apex.message.hidePageSuccess();',
'            gShowingSuccess = false;',
'        }',
'        // on any notification check if the model has changes and update save action state.',
'        // this updates the button disabled state.',
'        apex.actions.lookup("save-all").disabled = !model.isChanged();',
'        apex.actions.update("save-all");',
'        // update tab to reflect state',
'        // todo make this accessible by adding something more than just color to indicate the changed/error states',
'        tabs$.find(".ui-tabs-nav").find(".is-error,.is-changed").removeClass("is-error is-changed");',
'        model.getChanges().forEach(function(change) {',
'            var recId = model.getRecordId(change.record);',
'            if (change.inserted || change.updated) {',
'                tabs$.find(".ui-tabs-tab[data-name=''" + recId + "'']").addClass("is-changed");',
'            }',
'            // todo might be nice to show which fields have changed',
'        });',
'        model.getErrors().forEach(function(error) {',
'            var recId = model.getRecordId(error.record);',
'            // todo find some way to display whole record error messages',
'            tabs$.find(".ui-tabs-tab[data-name=''" + recId + "'']").addClass("is-error");',
'        });',
'        if (changeType === "refreshRecords") {',
'            // make sure tab has correct record id and title',
'            for (i = 0; i < change.records.length; i++) {',
'                id = change.recordIds[i];',
'                newId = change.newIds[id];',
'                if (newId) {',
'                    tabs$.find("[data-name=''" + id + "'']").attr("data-name", newId);',
'                    id = newId;',
'                }',
'                tabs$.find(".ui-tabs-tab[data-name=''" + id + "''] a").text(model.getValue(change.records[i],"ENAME"));',
'            }',
'        }',
'    },',
'    progressView: $("#tabs")',
'});',
'',
'// Tabs widget requires there be at least one tab',
'// The default instructions tab should have a tab panel but don''t want to see the tab. See CSS rule.',
'$("[aria-controls=''instructions'']").addClass("default-no-tab");',
'',
'// add save action.',
'apex.actions.add({',
'    name: "save-all",',
'    label: null, // get label from the button',
'    disabled: true,',
'    shortcut: "Alt+/,S",',
'    action: function() {',
'        var p;',
'        if (!model.hasErrors()) {',
'            // want to save all the related views if there are more than just what is currently in use',
'            p = model.save();',
'            if (p) {',
'                p.done( function( _, responseData ) {',
'                    var region, message;',
'                    if ( responseData.regions ) {',
'                        region = responseData.regions[0];',
'                        if ( region.fetchedData && region.fetchedData.successMessage ) {',
'                            message = region.fetchedData.successMessage;',
'                        } else {',
'                            message = apex.lang.getMessage("APEX.IG.CHANGES_SAVED");',
'                        }',
'                        apex.message.showPageSuccess(message);',
'                        gShowingSuccess = true;',
'                        status = "success";',
'                    }',
'                } ).fail( function( errors, textStatus, errorThrown ) {',
'                    if ($.isArray(errors)) {',
'                        // fix up errors so they map on the the right tab form elements',
'                        // errors come back applicable for updating the model but',
'                        // we want them to apply to the cloned page items',
'                        errors.forEach(function(e) {',
'                            var tabPanel$ = $(".ui-tabs-panel[data-name=''" + e.recordId + "'']")',
'                                id = tabPanel$.find("[data-bind=''" + e.columnName + "'']").prop("id");',
'                            delete e.columnName;',
'                            e.pageItem = id;',
'                        });',
'                        apex.message.clearErrors();',
'                        apex.message.showErrors( errors );',
'                    } else {',
'                        apex.message.alert( textStatus || errorThrown, function() { });',
'                    }',
'                } );',
'                // disable save button to avoid double save model listener will cause to enable',
'                apex.actions.disable("save-all");',
'            }',
'        } else {',
'            apex.message.alert( apex.lang.getMessage( "APEX.CORRECT_ERRORS" ), function() {',
'                // todo focus first error',
'            });',
'        }',
'    }',
'});',
'',
'// so clicking on error message links will open the correct tab',
'apex.message.addVisibilityCheck( function( id ) {',
'    var tabId = $("#" + id).closest(".ui-tabs-panel")[0].id,',
'        tab$ = $("[aria-controls=''" + tabId + "'']");',
'    // activate tab',
'    $("#tabs").tabs("option", "active", tab$.index());',
'});',
''))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
