wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(4228288181724380168)
,p_event_id=>wwv_flow_imp.id(4228288121338380167)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_affected_elements_type=>'REGION'
,p_affected_region_id=>wwv_flow_imp.id(4209251588668246199)
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var id, index, tabPanel$, title, content, content$, template$, recId, promise, prefix, datePickerId,',
'    tabs$ = $("#tabs"),',
'    empid = $v("P29_EMPLOYEE");',
'',
'function binding(recId, formId) {',
'    app.simpleBinding(app.gEmpModel, recId, $("#" + formId));',
'}',
'',
'tabPanel$ = $(".ui-tabs-panel[data-name=''" + empid + "'']");',
'if (empid !== "NEW" && tabPanel$[0]) {',
'    // if not a new employee and the employee is already open switch to it.',
'    id = tabPanel$[0].id;',
'    index = $("#tabs").find("[aria-controls=''" + id + "'']").index();',
'    tabs$.tabs("option", "active", index);',
'} else {',
'    if (empid === "NEW") {',
'        title = "New Employee"; // todo use message',
'    } else {',
'        title = apex.item("P29_EMPLOYEE").displayValueFor(empid);',
'    }',
'',
'    // copy the template make the IDs unique and remove the name',
'    // because these form elements are not for sumbmitting.',
'    // Using standard page items as a template form will not work in general',
'    // DAs, cascading LOV, etc will not work. Some item types need to be',
'    // initialized. After the clone/copy the form elements are not items any more.',
'    template$ = $("#templateTab");',
'    content$ = template$.clone();',
'    prefix = "T_" + app.gIdCounter + "_";',
'    content$.find("[id]").each(function() {',
'        var forAttr = $(this).attr("for");',
'        this.id = prefix + this.id;',
'        $(this).removeAttr("name");',
'        if (forAttr) {',
'            $(this).attr("for", prefix + forAttr);',
'        }',
'    });',
'    app.gIdCounter += 1;',
'',
'    content = content$.html();;',
'    id = tabs$.tabs("add", {',
'        title: title,',
'        content: content,',
'        removable: true,',
'        makeActive: true',
'    });',
'    // Many item types will work fine when copied given the above fix ups but ',
'    // more complex widgets may need to be initialized; just look at what APEX does to init them.',
'    datePickerId = "#" + prefix + "P29_HIREDATE";',
'    $(datePickerId).removeClass("hasDatepicker")',
'        .parent().find(".ui-datepicker-trigger").remove(); // so it can be initialized',
'    apex.widget.datepicker(datePickerId, {',
'        buttonImageOnly: false,',
'        buttonText: ''<span class="a-Icon icon-calendar"></span><span class="u-VisuallyHidden">Popup Calendar: Hiredate<span>'',',
'        showTime: false,',
'        defaultDate : new Date(),',
'        showOn : "button",',
'        showOtherMonths: false,',
'        changeMonth: true,',
'        changeYear: true }, "dd-M-y", "en");',
'    $(datePickerId).next(''button'').addClass(''a-Button a-Button--calendar'');',
'',
'    if (empid === "NEW") {',
'        title = "New Employee"; // todo use message',
'        recId = app.gEmpModel.insertNewRecord();',
'        binding(recId, id);',
'        // the model listener will try to update the state of this tab but the tab',
'        // is not yet associated with the record so do it explicitly here.',
'        $("[aria-controls=''" + id + "'']").addClass("is-changed");',
'    } else {',
'        // Add record to the model',
'        promise = app.fetchRecord(app.gEmpModel, empid);',
'        recId = empid;',
'        promise.done(function() {',
'            binding(recId, id);',
'        })',
'        .fail(function(error) {',
'            apex.message.alert("Error fetching record " + recId + "Reason: " + error.message);',
'        });',
'    }',
'',
'    $("#" + id).attr("data-name", recId)',
'        .attr("data-prefix", prefix);',
'    $("[aria-controls=''" + id + "'']").attr("data-name", recId);',
'}',
'',
'apex.theme.closeRegion(this.affectedElements);',
''))
);
