wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(4228288885232380175)
,p_event_id=>wwv_flow_imp.id(4228288847101380174)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if (this.browserEvent.originalEvent) {',
'    var ok, rec, model,',
'        tabId = this.data.id,',
'        tab$ = $("[aria-controls=''" + tabId + "'']"),',
'        recId = tab$.attr("data-name");',
'',
'    if (tab$.hasClass("is-changed") || tab$.hasClass("is-error")) {',
'        this.browserEvent.preventDefault();',
'        apex.message.confirm("There are changes are you sure you want to close this tab?", function(ok) {',
'            if (ok) {',
'                $("#tabs").tabs("remove", tabId);',
'            }',
'        });',
'        /* this works around a bug prior to 19.1 in apex.message.confirm ',
'        setTimeout(function() {',
'            ok = confirm("There are changes are you sure you want to close this tab?");',
'            if (ok) {',
'                model = app.gEmpModel;',
'                rec = model.getRecord(recId);',
'                if (model.getRecordMetadata(recId).inserted) {',
'                    model.deleteRecords([rec]);',
'                } else if (model.canRevertRecord(rec)) {',
'                    model.revertRecords([rec]);',
'                }',
'                $("#tabs").tabs("remove", tabId);',
'            }',
'        }, 1); */',
'    }',
'}'))
);
