wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(4228289122552380177)
,p_event_id=>wwv_flow_imp.id(4228288988065380176)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var newTab$ = this.data.newTab;',
'if (newTab$.hasClass("default-no-tab") && newTab$.parent().children().length > 1) {',
'    // don''t let the default null tab be active if there are other tabs',
