prompt --application/pages/page_00030
begin
wwv_flow_imp_page.create_page(
 p_id=>30
,p_name=>'Custom Progress'
,p_step_title=>'Custom Progress'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// Add the progress indicator. An alternative would be to add this to a page template.',
'$("#t_Header .t-Header-logo").append(''<div id="progress" class="progress-bar stripes"><span></span></div>'');',
''))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* progress */',
'#progress {',
'    float: right;',
'    margin-top: 5px;',
'}',
'.progress-bar {',
'    height: 25px;',
'    padding: 5px;',
'    width: 120px;',
'    font-size: 1rem;',
'    line-height: 15px;',
'}',
'.progress-bar.is-active {',
'    background-color: #1a1a1a;',
'    border-radius: 5px;',
'    box-shadow: 0 1px 5px #000 inset, 0 1px 0 #444;',
'}',
'.progress-bar.is-active span {',
'    display: inline-block;',
'    background-color: #34c2e3;',
'    width: 100%;',
'    height: 15px;',
'}',
'.stripes.is-active span {',
'    background-size: 30px 30px;',
'    background-image: linear-gradient(135deg, rgba(255, 255, 255, .15) 25%, transparent 25%,',
'                        transparent 50%, rgba(255, 255, 255, .15) 50%, rgba(255, 255, 255, .15) 75%,',
'                        transparent 75%, transparent);            ',
'    animation: animate-stripes 3s linear infinite;             ',
'}',
'',
'@keyframes animate-stripes {',
'    0% {background-position: 0 0;} 100% {background-position: 60px 0;}',
'}',
''))
,p_page_template_options=>'#DEFAULT#'
,p_page_component_map=>'21'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(32570058676930830626)
,p_plug_name=>'Notes'
,p_region_template_options=>'#DEFAULT#:js-useLocalStorage:is-collapsed:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(35108653483362181373)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>This page demonstrates how you can have control over the progress indication',
'shown by Interactive Grid. On twitter people have ',
'<a target="_blank" href="https://twitter.com/OliverLemm/status/1085837449350135809">asked</a> for more ',
'<a target="_blank" href="https://twitter.com/Ronny_Weiss_/status/1085955882545004544">control</a> over progress indicators.',
'This page has a global progress indicator in the title bar.',
'You may need to use developer tools to throttle the network requests in order',
'to better see the progress. Starting in 19.1 a default progress indicator is shown for ',
'IG save requests.</p>',
'<p>Note: People have sometimes used the <code>apexbeforerefresh</code> and <code>apexafterrefresh</code>',
'events to show progress with other kinds of regions but this is not a robust ',
'method because <code>apexafterrefresh</code> is not guaranteed to happen. Also these events',
'<a target="_blank" href="http://hardlikesoftware.com/weblog/2017/03/31/how-to-hack-apex-interactive-grid-part-4/">do not apply</a> to IG.</p>',
'<p>Demonstrates:<br>',
'Using the model option <code>makeLoadingIndicator</code> and interactiveGrid widget option',
'<code>saveLoadingIndicator</code>. The progress indicator used is just an example.',
'It should be clear that since you can run code at the start and end of the request (actually via apex.util.delayLinger)',
'that any kind of progress indication should be possible.',
'<br>Customizations:<br>',
'Page attribute Execute when Page Loads adds markup for the progress indicator.',
'The needed CSS is in CSS: Inline. The integration with IG is in Advanced: JavaScript Initialization.',
'</p>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
