prompt --application/pages/page_00031
begin
wwv_flow_imp_page.create_page(
 p_id=>31
,p_name=>'Simple Grid'
,p_step_title=>'Simple Grid'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// because of a-Tabs-panel display:none and when the tabs remember the last used tab',
'// need to call forceActive so that the regions are notified that they are visible.',
'// rds is the static id of the RDS region adjust as needed.',
'var activeTab = $("#rds").find(".a-Tabs").aTabs("getActive");',
'activeTab.forceActive();',
'',
'function resizeMainContent() {',
'    var sgHeight,',
'        height = $(window).height(); // start with the window height',
'',
'    // subtract off all the fixed height regions and header',
'    height -= $(".t-Header").outerHeight();',
'    height -= $("#t_Body_content_offset").height(); // this takes the breadcrumb area into consideration',
'    height -= $(".t-Footer").outerHeight();',
'    height -= 32; // for body padding adjust or remove if change body padding',
'',
'    // then set the height of the regions that will stretch',
'    // setOuterHeight takes into consideration the borders etc. on the grid itself.',
'    ["#notes", "#notes .t-Region-body", "#emp","#tableBrowser"].forEach(function(sel) {',
'        apex.util.setOuterHeight($(sel), height);',
'    });',
'    sgHeight = height;',
'    sgHeight -= $("#emp .t-Region-header").outerHeight();',
'    sgHeight -= $("#emp .t-Region-buttons").outerHeight();',
'    apex.util.setOuterHeight($("#emp .sizer"), sgHeight);',
'    sgHeight = height;',
'    sgHeight -= $("#tableBrowser .container:first").outerHeight();',
'    // subtract the height of the header but the tableData header may be invisible. The noTableData header is the same height so use whichever is visible',
'    sgHeight -= $("#tableBrowser .t-Region-header").filter(":visible").last().outerHeight();',
'    apex.util.setOuterHeight($("#tableData .sizer"), sgHeight);',
'}',
'$(window).on("apexwindowresized", resizeMainContent);',
'resizeMainContent();',
'',
'// init filters',
'$("#rds").on("atabsactivate", function(event, ui) {',
'    var i, col, columns,',
'    colOptions = "<option value=''''></option>";',
'',
'    resizeMainContent();',
'    if (ui.active.href === "#emp") {',
'        setTimeout(function() {',
'            columns = apex.region("emp").call("getColumns");',
'            for (i = 0; i < columns.length; i++) {',
'                col = columns[i];',
'                if ( !(col.hidden && !col.canHide) && (col.label || col.heading) ) {',
'                    colOptions += "<option value=''" + col.property + "''>" + apex.util.escapeHTML( col.label || col.heading) + "</option>";',
'                }',
'            }',
'            $("#P31_F1_COL, #P31_F2_COL, #P31_F3_COL").html(colOptions);',
'        }, 1);',
'    }',
'});',
'',
'// handle table change but with debounce',
'function updateTableData() {',
'    var title,',
'        tableName = $v("P31_TABLE"),',
'        hasData = tableName !== "";',
'',
'    // using apexaftershow/hide events to get visibility change behavior like the Show/Hide DAs',
'    $("#tableData").toggle(hasData).trigger(hasData ? "apexaftershow" : "apexafterhide");',
'    $("#noTableData").toggle(!hasData).trigger(!hasData ? "apexaftershow" : "apexafterhide");',
'    if (hasData) {',
'        title = "Data for " + tableName; // todo i18n use a message',
'        apex.region("tableData").changeColumns(tableName);',
'    } else {',
'        title = "Data";',
'    }',
'    $("#tableData .t-Region-title").text(title);',
'}',
'',
'$("#P31_TABLE").change(apex.util.debounce(function() {',
'    updateTableData();',
'}, 300));',
'updateTableData();',
''))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.a-Tabs-panel {',
'    display:none;',
'}',
'.a-GV-rowHeader {',
'    font-weight: bold;',
'}',
'/* If trying to maximize the screen space available for the wide grid region',
' * you may not want much or any padding on the main body.',
'',
'.t-Body-contentInner {',
'    padding: 0;',
'}',
'*/',
'/* The region heights will be set in JavaScript so don''t want the body to ',
' * have an explicit height */',
'.t-Body-content {',
'    min-height: initial;',
'}',
'/* If the main page never scrolls then there is little point in a back to top button',
' * You could hide the while footer (.t-Footer) but at that point you may want',
' * to look at creating a custom page template such as ''Fit to Window'' that doesn''t have a footer.',
' */',
'.t-Footer-top {',
'    display: none;',
'}',
'/* let columnheader wrap for the table browser grid */',
'#tableData .a-GV-headerLabel {',
'    white-space: normal;',
'}'))
,p_page_template_options=>'#DEFAULT#'
,p_page_component_map=>'17'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3895562794875359065)
,p_plug_name=>'Simple Grid'
,p_region_name=>'emp'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--hideHeader:t-Region--noBorder:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(35108658789039181378)
,p_plug_display_sequence=>30
