wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(4011762188730673715)
,p_plug_name=>'Data'
,p_region_name=>'tableData'
,p_parent_plug_id=>wwv_flow_imp.id(4011762059151673714)
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--scrollBody'
,p_region_attributes=>'style="display:none;"'
,p_plug_template=>wwv_flow_imp.id(35108658789039181378)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   l_cols varchar2(32767);',
'   l_table varchar2(128) := case when :P31_TABLE is null then ''DUAL'' else :P31_TABLE end;',
'begin',
'    if :P31_TABLE is null then',
'        -- these are design time columns',
'        l_cols := ''''''a'''' "VARCHAR2", 2 "NUMBER", to_date(''''1900-01-01'''', ''''YYYY-MM-DD'''') "DATE", '' ||',
'          ''to_timestamp(''''1900-01-01'''', ''''YYYY-MM-DD'''') "TIMESTAMP", '' ||',
'          ''to_timestamp_tz(''''1900-01-01'''', ''''YYYY-MM-DD'''') "TIMESTAMP WITH TIME ZONE", ''||',
'          ''to_timestamp_tz(''''1900-01-01'''', ''''YYYY-MM-DD'''') "TIMESTAMP WITH LOCAL TIME ZONE"'';',
'    else',
'        select listagg( column_name, ''", "'') within group (order by column_id) column_name into l_cols',
'            from all_tab_columns ',
'        where table_name = l_table;',
'        if l_cols is not null then',
'            l_cols := ''"'' || l_cols || ''"'';',
'        else',
'            l_cols := ''1'';',
'        end if;',
'    end if;',
'    return ''select '' || l_cols || '' from '' || l_table;',
'end;'))
,p_plug_source_type=>'PLUGIN_JJS_SIMPLE_GRID'
,p_ajax_items_to_submit=>'P31_TABLE,P31_SCHEMA'
,p_plugin_init_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function(options) {',
'    options.persistColumnStatePrefix = "&P31_TABLE.";',
'    return options;',
'}'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'SORT:REORDER:RESIZE',
  'attribute_02', 'Y',
