wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(4110693292314776884)
,p_event_id=>wwv_flow_imp.id(4110693174025776883)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var i, col, type, value, values,',
'    filters = [];',
'for (i = 1; i <= 3; i++) {',
'    col = $v("P31_F" + i + "_COL");',
'    type = parseInt($v("P31_F" + i + "_TYPE"), 10);',
'    value = $v("P31_F" + i + "_VALUE");',
'    if (col) {',
'        if ( type === 17 || type === 18) { // between, not between',
'            values = value.split(/;\s*/);',
'            filters.push({',
'                column: col,',
'                type: type,',
'                fromValue: values[0],',
'                toValue: values[1]',
'            });',
'        } else if ( type === 15 || type === 16) { // in, not in',
'            filters.push({',
'                column: col,',
'                type: type,',
'                values: value.split(/;\s*/)',
'            });',
'        } else if ( type === 7 || type === 8 ) { // null, not null',
'            filters.push({',
'                column: col,',
'                type: type',
'            });',
'        } else {',
'            filters.push({',
'                column: col,',
'                type: type,',
'                value: value',
'            });',
'        }',
'    }',
'}',
'apex.region("emp").setFilters(filters);'))
);
wwv_flow_imp_page.create_page_da_event(
 p_id=>wwv_flow_imp.id(4110693331853776885)
,p_name=>'show/hide value based on filter type'
,p_event_sequence=>110
,p_triggering_element_type=>'JQUERY_SELECTOR'
,p_triggering_element=>'.filter-type'
,p_bind_type=>'bind'
,p_execution_type=>'IMMEDIATE'
,p_bind_event_type=>'change'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(4110693467365776886)
,p_event_id=>wwv_flow_imp.id(4110693331853776885)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var filterItem = this.triggeringElement.id,',
'    filterType = $v(filterItem),',
'    row_num = /_F(\d*)_/.exec(filterItem)[1],',
'    valItem = "P31_F" + row_num + "_VALUE";',
'',
'if (filterType === "7" || filterType === "8") {',
'    // null or not null need no value',
'    apex.item(valItem).hide();',
'} else {',
'    apex.item(valItem).show();',
'}',
''))
);
end;
/
