prompt --application/pages/page_00034
begin
wwv_flow_imp_page.create_page(
 p_id=>34
,p_name=>'Shared Model'
,p_step_title=>'Shared Model'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function resizeIg() {',
'    var newView,',
'        w = $(window).width(),',
'        actions = apex.region("emp").call("getActions"),',
'        curView = actions.get("change-view");',
'',
'    if (w < 640) {',
'        newView = "icon";',
'    } else {',
'        newView = "grid";',
'    }',
'    if (curView !== newView) {',
'        actions.set("change-view", newView);',
'    }',
'}',
'',
'$(window).on("apexwindowresized", resizeIg);',
'resizeIg();',
''))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.a-TMV-defaultIconView .a-IconList-item {',
'    position: relative;',
'    display: block;',
'    height: 200px;',
'    width: 98%;',
'}',
'.a-IconList-item .u-selector {',
'    position: absolute;',
'    top: 1px;',
'    left: 1px;',
'}',
'@media screen and (min-width: 600px) {',
'  .a-TMV-defaultIconView .a-IconList-item {',
'    width: 48%;',
'  }',
'}',
'@media screen and (min-width: 1500px) {',
'  .a-TMV-defaultIconView .a-IconList-item {',
'    width: 24%;',
'  }',
'}',
'',
'.emp-detail {',
'    list-style: none outside none;',
'    margin: 4px;',
'}',
'.emp-detail-item {',
'    border: 1px solid #262626;',
'    border-radius: 2px;',
'    margin: 16px 4px;',
'}'))
,p_page_template_options=>'#DEFAULT#'
,p_page_component_map=>'21'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(32570125228196555324)
,p_plug_name=>'Notes'
,p_region_template_options=>'#DEFAULT#:js-useLocalStorage:is-collapsed:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(35108653483362181373)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Normally each view (grid, icon, and detail) has its own model.',
'This means that they can have different sort orders (this was always intended ',
'because it matches the way Interactive Reports works even though prior to 19.1',
'icon and detail views didn''t support sorting at all) and if you make edits',
'in grid view the changes are not reflected in the other views (until after save',
'and refresh).',
'Other views like charts and future views such as group by have completely ',
'different model contents and therefore must be different.',
'There are advantages for views to share the same model where possible.',
'One is reducing the amount of data transfered to and stored on the client.',
'Another advantage is that changes made in one view are immediately visible in',
'the others.</p>',
'<p>This page demonstrates an experimental feature to share the model between ',
'the grid, icon, and detail views. It also has proof of conecpt responsive ',
'code that changes the view depending on the screen size; grid when wide and ',
'icon when narrow. This only makes sense because the views all share the same model.</p>',
'<p>Customizations:<br>',
'Custom markup for icon and details views and corresponding page inline CSS.',
'Advanced: JavaScript Initialization Code sets the options that specify a shared model.',
'The logic to change views according to screen size is in page attribute Execute when Page Loads.</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
