,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function(config) {',
'    // if you save the user settings or if you just want to hard code the options do this:',
'    // or the values can come from preference(s) rendered onto the page as JavaScript data or encoded in a hidden item.',
'    config.defaultGridViewOptions = {',
'//        skipReadonlyCells: true,',
'//        allowSelectHidden: true,',
'//        hideDeletedRows: true,',
'//        collapsibleControlBreaks: false',
'    };',
'',
'    config.initActions = function(actions) {',
'        var ig$ = $(actions.context);',
'',
'        function grid(opt, val) {',
'            var grid = ig$.interactiveGrid("getViews").grid;',
'            // make sure the grid view exists and is initalized',
'            // even though the settings menu should be disabled if the grid is not initalized it is best to be robust',
'            if (grid && grid.view$) {',
'                if (val !== undefined) {',
'                    grid.view$.grid("option", opt, val);',
'                } else {',
'                    return grid.view$.grid("option", opt);',
'                }',
'            }',
'            return false;',
'        }',
'',
'        actions.add([{',
'            name: "skip-readonly",',
'            label: "Skip Readonly Columns", // todo use labelKey with text messages for all these labels',
'            get: function() {',
'                return grid("skipReadonlyCells");',
'            },',
'            set: function(v) {',
'                grid("skipReadonlyCells", v);',
'            }',
'        }, {',
'            name: "select-collapsed",',
'            label: "Allow Select Collapsed",',
'            get: function() {',
'                return grid("allowSelectHidden");',
'            },',
'            set: function(v) {',
'                grid("allowSelectHidden", v);',
'            }',
'        }, {',
'            name: "hide-deleted-rows",',
'            label: "Hide Deleted Rows",',
'            get: function() {',
'                return grid("hideDeletedRows");',
'            },',
'            set: function(v) {',
'                grid("hideDeletedRows", v);',
'            }',
'        }, {',
'            name: "collapsible-breaks",',
'            label: "Collapsible Breaks",',
'            get: function() {',
'                return grid("collapsibleControlBreaks");',
'            },',
'            set: function(v) {',
'                var view;',
'                grid("collapsibleControlBreaks", v);',
'                // changing this after the view is initialized requires refreshing the grid view',
'                view = ig$.interactiveGrid("getViews").grid;',
'                if (view && view.view$) {',
'                    // this just rerenders the grid view it doesn''t change the model at all',
'                    view.refresh(); // warning refresh method of ig view interface not documented',
'                    // could do this instead',
'                    // view.view$.grid("refresh");',
'                }',
'            }',
'        }]);',
'    }',
'    var tb = $.apex.interactiveGrid.copyDefaultToolbar();',
'    tb.toolbarInsertAfter("actions_button", {',
'        type: "MENU",',
'        id: "settings_button",',
'        label: "Settings", // todo use labelKey with text messages for all these labels',
'        menu: {',
'            items: [',
'                {',
'                    type: "toggle",',
'                    action: "skip-readonly"                    ',
'                },',
'                {',
'                    type: "toggle",',
'                    action: "select-collapsed"                    ',
'                },',
'                {',
'                    type: "toggle",',
'                    action: "hide-deleted-rows"                    ',
'                },',
'                {',
'                    type: "toggle",',
'                    action: "collapsible-breaks"                    ',
'                }',
'            ]',
'        }',
'    });',
'    config.toolbarData = tb;',
'    return config;',
'}',
''))
);
