wwv_flow_imp_page.create_page(
 p_id=>39
,p_name=>'Remember Page'
,p_step_title=>'Remember Page'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// create the app namespace from the IIFI return value',
'// this should go in a file',
'var app = (function($) {',
'    "use strict";',
'',
'    var gInitialPages = {}; // map regionId -> {} map view -> init info',
'',
'    var urlParts = window.location.search.split(":"),',
'        resetPagination = urlParts[5] && urlParts[5].match(/RP/);',
'',
'    // Move info from the session storage into gInitialPages structure so that',
'    // it can be used just once as the various widgets get initialized.',
'    function setInitInfo(store, regionId, key) {',
'        var offset, count, info,',
'            sel = store.getItem(key + "LastSelection"),',
'            lastPage = store.getItem(key + "LastPage");',
'',
'        // never trust session/local storage - validate!',
'        if (lastPage && lastPage.match(/\d+:\d+/)) {',
'            lastPage = lastPage.split(":");',
'            offset = parseInt(lastPage[0], 10);',
'            count = parseInt(lastPage[1], 10);',
'            info = {offset: offset, count: count};',
'            if (sel) {',
'                // not much validation of the selection that can be done',
'                info.sel = sel;',
'            }',
'            apex.util.getNestedObject(gInitialPages, regionId)[key] = info;',
'        }',
'    }',
'',
'    /*',
'     * At this point we don''t know all the IG regions on the page because they ',
'     * haven''t been inintialized yet. $(".a-IG") won''t work yet!',
'     * But only care if info was put in sesson storage so use info from the keys',
'     * to get all the region ids.',
'     */',
'    var i, parts, len, store, regionId,',
'        igRegions = {};',
'',
'    store = apex.storage.getScopedSessionStorage({usePageId: true});',
'    len = store.length;',
'    for (i = 0; i < len; i++) {',
'        parts = store.key(i).split("."); // assume region id doesn''t include "."!',
'        igRegions[parts[3]] = 1;',
'    }',
'    igRegions = Object.keys(igRegions);',
'',
'    if (resetPagination) {',
'        // reset pagination for each of the possible views of each IG region',
'        for (i = 0; i < igRegions.length; i++) {',
'            regionId = igRegions[i];',
'            store = apex.storage.getScopedSessionStorage({usePageId: true, regionId: regionId});',
'            store.removeItem("gridLastPage");',
'            store.removeItem("iconLastPage");',
'            store.removeItem("detailLastPage");',
'        }',
'    } else {',
'        // prepare to restore the pagination offset for each of the possible veiws of each IG region',
'        for (i = 0; i < igRegions.length; i++) {',
'            regionId = igRegions[i];',
'            // return to remembered IG page',
'            // store the lastPage info for when the IG view widgets are initalized',
'            store = apex.storage.getScopedSessionStorage({usePageId: true, regionId: regionId});',
'            setInitInfo(store, regionId, "grid");',
'            setInitInfo(store, regionId, "icon");',
'            setInitInfo(store, regionId, "detail");',
'        }',
'    }',
'',
'    /*',
'     * Step 1',
'     * When the page or selection changes remember it per view',
'     * Step 2',
'     * Store the information in browser session storage',
'     */',
'    function initRememberPageHandlers() {',
'        $(".a-IG").on("gridpagechange tablemodelviewpagechange", function(event, data) {',
'            var initInfo, sel,',
'                ig$ = $(this),',
'                regionId = this.id, // not exactly the region id but in the spirt of the regionId option of getScopedSessionStorage',
'                store = apex.storage.getScopedSessionStorage({usePageId: true, regionId: regionId}),',
'                viewId = ig$.interactiveGrid("getCurrentViewId");',
'',
'            if (viewId.match(/icon|grid|detail/)) {',
'                store.setItem(viewId + "LastPage", data.offset + ":" + data.count);',
'                console.log("SAVED page change: ", regionId, viewId, data );',
'                // Also part of step 3 restore the selection',
'                initInfo = gInitialPages[regionId] && gInitialPages[regionId][viewId];',
'                if (initInfo && initInfo.sel) {',
'                    sel = initInfo.sel;',
'                    // because when clicking on a link the row/record isn''t selected allow an item ',
'                    // to override the selection.',
'                    if ( $v("P39_SELECTION_OVERRIDE") ) {',
'                        sel = $v("P39_SELECTION_OVERRIDE");',
'                    }',
'                    ig$.interactiveGrid("setSelectedRecords", sel.split("|"));',
'                    delete initInfo.sel;',
'                }',
'            }',
'        });',
'        $(".a-IG").on("interactivegridselectionchange", function(event, data) {',
'            var sel, model,',
'                ig$ = $(this),',
'                regionId = this.id, // not exactly the region id but...',
'                store = apex.storage.getScopedSessionStorage({usePageId: true, regionId: regionId}),',
'                view = ig$.interactiveGrid("getCurrentView"),',
'                viewId = view.internalIdentifier;',
'',
'            if (viewId.match(/icon|grid/)) {',
'                model = view.model;',
'                // turn all the selected records into a | separated list of primary keys',
'                sel = ig$.interactiveGrid("getSelectedRecords").map( function(r) { return model.getRecordId(r); } ).join("|");',
'                store.setItem(viewId + "LastSelection", sel);',
'                console.log("SAVED selection change: ", regionId, viewId, sel );',
'            }',
'        });',
'    }',
'',
'    /*',
'     * Step 3',
'     * Restore the IG page (row offset really) when IG view widgets are initalized.',
'     * See code above for how the session store info was gathered and made available for this step.',
'     */',
'    /*',
'     * The grid and tableModelView widgets just don''t let you initialize them',
'     * with a starting offset. They always start at 0. This is a problem for',
'     * returning to a specific page. (See comments below on the first failed attempt that lead to this solution)',
'     * Extend the widgets in-place to allow setting an initial offset',
'     * Needs to happen after interactiveGrid and related widgets are loaded but before they are initalized',
'     *',
'     * Warning: using undocumented internal properties of the grid and tableModelView widgets.',
'     */',
'    $(function() {',
'        $.widget( "apex.grid", $.apex.grid, {',
'            refresh: function( focus ) {',
'                var regionId, initInfo;',
'                // if this grid is in an IG view',
'                if ( this.element.hasClass("a-IG-gridView") ) {',
'                    regionId = this.element.closest(".a-IG")[0].id; // id of IG region',
'                    initInfo = gInitialPages[regionId] && gInitialPages[regionId].grid;',
'                    if (initInfo && initInfo.offset) {',
'                        this.pageOffset = initInfo.offset;',
'                        delete initInfo.offset;',
'                        if (this.pageOffset > 0) {',
'                            // Workaround a failed assumption in the model that the first request',
'                            // will be for offset 0.',
'                            // Warning using undocumented member _data.',
'                            this.model._data.length = 1;',
'                        }',
'                        console.log("RESTORE page offset", regionId, "grid", this.pageOffset, this.pageSize);',
'                    }',
'                }',
'                this._super( focus );',
'            }',
'        });',
'        $.widget( "apex.tableModelView", $.apex.tableModelView, {',
'            refresh: function( focus ) {',
'                var regionId, initInfo, viewId, key;',
'',
'                // table model view is used for both icon view and detail view so figure out which one this instance is',
'                if ( this.element.hasClass("a-IG-iconView") ) {',
'                    viewId = "icon";',
'                } else if ( this.element.hasClass("a-IG-detailView") ) {',
'                    viewId = "detail";',
'                }',
'                if ( viewId ) {',
'                    key = viewId;',
'                    regionId = this.element.closest(".a-IG")[0].id; // id of IG region',
'                    initInfo = gInitialPages[regionId] && gInitialPages[regionId][key];',
'                    if (initInfo && initInfo.offset) {',
'                        this.pageOffset = initInfo.offset;',
'                        delete initInfo.offset;',
'                        if (this.pageOffset > 0) {',
'                            // Workaround a failed assumption in the model that the first request',
'                            // will be for offset 0.',
'                            // Warning using undocumented member _data.',
'                            this.model._data.length = 1;',
'                        }',
'                        console.log("RESTORE page offset", regionId, viewId, this.pageOffset, this.pageSize);',
'                    }',
'                }',
'                this._super( focus );',
'            }',
'        });',
'    });',
'',
'    /*',
'     * The following was my first attempt at a solution. The idea was to use',
'     * the gotoPage method after the page loads and the IG widget is created.',
'     * The problems were lazy loading didn''t work, Required Show Total Row Count',
'     * count to be true. Would likely be confused by changes in region size when',
'     * using auto rows per page. Was inefficent because the first page of ',
'     * data would always be fetched. The following is incomplete - it doesn''t work.',
'     * I left it in case others want to go down this route.',
'     */',
'',
'    // A goto page function that works no matter what the current view',
'    // seems like something the IG widget should have built in.',
'    // this was part of prototyping and may have other uses but didn''t use it in the end',
'    function gotoIGPage(region, page) {',
'        var ig = apex.region(region),',
'            view = ig.call("getCurrentView"),',
'            viewId = view.internalIdentifier;',
'',
'        if (viewId === "grid" && !view.singleRowMode) {',
'            view.view$.grid("gotoPage", page);',
'        } else if (viewId === "icon" || viewId === "detail") {',
'            view.view$.tableModelView("gotoPage", page);',
'        }',
'    }',
'',
'    /*',
'     * Step 3',
'      * When an IG is created try to restore the remembered page and selection',
'     */',
'/*',
'    $(document).on("interactivegridcreate", function(event) {',
'        var store, viewId, lastPage, offset, count, sel,',
'            ig$ = $(event.target),',
'            regionId = ig$[0].id;',
'',
'        // check if should return to remembered IG page',
'        if (resetPagination) {',
'            // reset pagination for each of the possible views',
'            store = apex.storage.getScopedSessionStorage({usePageId: true, regionId: regionId});',
'            store.removeItem("gridLastPage");',
'            store.removeItem("iconLastPage");',
'            store.removeItem("detailLastPage");',
'        } else {',
'            // return to remembered IG page',
'            //',
'            // At this point if the IG is lazy loaded the request for the first data page',
'            // is already sent and waiting for it to come back and be rendered.',
'            // If it is not lazy loaded the first page is already rendered from',
'            // the model data that is in the HTML document. Either way it was a waste',
'            // to get and/or render the first page if we are going to a different remembered page.',
'            //',
'            store = apex.storage.getScopedSessionStorage({usePageId: true, regionId: regionId});',
'            viewId = ig$.interactiveGrid("getCurrentViewId");',
'            lastPage = store.getItem(viewId + "LastPage");',
'            // never trust session/local storage - validate!',
'            if (lastPage && lastPage.match(/\d+:\d+/)) {',
'                lastPage = lastPage.split(":");',
'                offset = parseInt(lastPage[0], 10);',
'                count = parseInt(lastPage[1], 10);',
'                // timing is important. if lazy loading the view would be fetching data now and the following would fail',
'                // would need to wait until the first fetch is done before going to a new page',
'                gotoIGPage("people", offset / count);',
'            }',
'            sel = store.getItem(viewId + "LastSelection");',
'            if (sel && sel.length) {',
'                // if have to fetch data first then this doesn''t work. need to wait until after data is rendered',
'                ig$.interactiveGrid("setSelectedRecords", sel.split("|"));',
'            }',
'        }',
'    });',
'*/',
'    // return app namespace',
'    return {',
'        gotoIGPage: gotoIGPage,',
'        initRememberPageHandlers: initRememberPageHandlers',
'    };',
'})(apex.jQuery);',
''))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// do this after all IGs on the page have been initalized',
'app.initRememberPageHandlers();'))
,p_page_template_options=>'#DEFAULT#'
,p_page_component_map=>'18'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(4371940376044059525)
,p_plug_name=>'People IR'
,p_region_name=>'peopleIR'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(35108658789039181378)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select id, ',
'       name,',
'       country,',
'       rating,',
'       from_yr,',
'       to_yr,',
'       link,',
'       category,',
'       gender,',
'       case CATEGORY',
'            when ''S_T'' then ''fa fa-rocket''',
'            when ''P'' then ''fa fa-university''',
'            when ''A'' then ''fa fa-paint-brush''',
'            when ''S'' then ''fa fa-bicycle''',
'            when ''B_L'' then ''fa fa-money''',
'            else ''fa fa-question''',
'       end as icon,',
'       apex_util.prepare_url(',
'           ''f?p='' || :APP_ID || '':40:''|| :APP_SESSION ||''::''|| :DEBUG ||''::P40_ID:''|| id',
'       ) as page_link',
'   from eba_demo_ig_people'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_display_condition_type=>'NEVER'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>8.5
,p_prn_height=>11
