,p_name=>'Custom Popup Test In Dialog'
,p_page_mode=>'MODAL'
,p_step_title=>'Custom Popup Test In Dialog'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var app = {};',
'(function(app, $) {',
'    function getProp(rootObject, propPath) {',
'        var o = rootObject;',
'        propPath.split(".").forEach(function(p) {',
'            if ( o[p] === undefined ) {',
'                o[p] = {};',
'            }',
'            o = o[p];',
'        });',
'        return o;',
'    }',
'    app.getProp = getProp;',
'',
'    app.simpleEval = function(exp) {',
'        var tokens = [], op,',
'            result;',
'',
'        function evalExpr(tokens) {',
'            var t, n1, op, n2, r;',
'            t = tokens.shift();',
'            if (t && t.type === "num") {',
'                n1 = t.val;',
'            } else {',
'                throw new Error("Number expected");',
'            }',
'            t = tokens.shift();',
'            if (!t) {',
'                return n1; // just a number',
'            } else if (t.type === "op") {',
'                op = t.val;',
'                if (op === "*" || op === "/") {',
'                    t = tokens.shift();',
'                    if (t && t.type === "num") {',
'                        n2 = t.val;',
'                    } else {',
'                        throw new Error("Number expected");',
'                    }',
'                    if (op === "*") {',
'                        r = n1 * n2;',
'                    } else if (op === "/") {',
'                        r = n1 / n2;',
'                    }',
'                    tokens.unshift({type:"num",val:r});',
'                    return evalExpr(tokens);',
'                } else {',
'                    n2 = evalExpr(tokens);',
'                    if (op === "+") {',
'                        return n1 + n2;',
'                    } else if (op === "-") {',
'                        return n1 - n2;',
'                    }',
'                }',
'            } // else',
'            throw new Error("Operator expected ''+ - * /''");',
'        }',
'        exp.replace(/(-?\d+(\.\d)?)|([+-\/*])|\s*/g, function(match, num, p2, op) {',
'            if (num) {',
'                tokens.push({type: "num", val: parseFloat(num)});',
'            } else if (op) {',
'                tokens.push({type: "op", val: op});',
'            }',
'        });',
'        try {',
'            result = evalExpr(tokens);',
'        } catch(e) {',
'            result = e;',
'        }',
'        return result;',
'    }',
'',
'',
'    app.initIGforPopupLov = function(config) {',
'        var tb,',
'            feat = app.getProp(config, "views.grid.features");',
'        feat.singleRowView = false;',
'        feat.highlight = false;',
'        feat.aggregate = false;',
'        config.defaultGridViewOptions = {',
'            footer: false',
'        }',
'        tb = app.getProp(config, "toolbar");',
'        tb.columnSelection = false;',
'        tb.actionMenu = false;',
'        config.reportSettingsArea = false;',
'        config.initActions = function(a) {',
'            a.hide("chart-view");',
'            replaceIgSearch(a);',
'        };',
'        return config;',
'    };',
'',
'    function replaceIgSearch(a) {',
'        var sortAction = a.lookup("search"),',
'            ig$ = $(a.context);',
'',
'        sortAction.action = function() {',
'            sortAction.getSearchValue( function ( value ) {',
'                var i, filter, filterId, filters;',
'',
'                // search always applies to the first row filter and assume always not case sensitive',
'                filters = ig$.interactiveGrid("getFilters");',
'                for (i = 0; i < filters.length; i++) {',
'                    if (filters[i].type === "row" ) {',
'                        filterId = filters[i].id;',
'                        break;',
'                    }',
'                }',
'                if ( value ) {',
'                    filter = {',
'                        type: "row",',
'                        value: value,',
'                        isCaseSensitive: false',
'                    };',
'                    if ( filterId ) {',
'                        ig$.interactiveGrid("updateFilter", filterId, filter)',
'                    } else {',
'                        ig$.interactiveGrid("addFilter", filter );',
'                    }',
'                } else if (filterId ) {',
'                    ig$.interactiveGrid( "deleteFilter", filterId );',
'                } else {',
'                    // Just refresh if we have no search term',
'                    // think should this just do nothing?',
'                    ig$.interactiveGrid("refresh");',
'                }',
'            } );',
'        }',
'    }',
'',
'    function initIGDialog(dialogId, igId, valProp, dispProp, extraCols) {',
'        var igDlg$ = $("#" + dialogId),',
'            widget = igDlg$.is(":data(apexPopup)") ? "popup" : "dialog",',
'            inst = igDlg$.data(widget === "dialog" ? "ui-dialog" : "apex-popup"),',
'            ig$ = apex.region(igId).widget();',
'',
'        function save() {',
'            var i, rec,',
'                result = {},',
'                r = apex.region(igId),',
'                multi = r.call("getCurrentView").view$.grid("option", "multiple"),',
'                model = r.call("getCurrentView").model,',
'                records = r.call("getSelectedRecords");',
'',
'            if (records.length > 0) {',
'                if (multi) {',
'                    if (dispProp) {',
'                        result.d = "";',
'                    }',
'                    result.v = "";',
'                    for (i = 0; i < records.length; i++) {',
'                        rec = records[i];',
'                        if (dispProp) {',
'                            if (i > 0) {',
'                                result.d += ", ";',
'                            }',
'                            result.d += model.getValue(rec, dispProp);',
'                        }',
'                        if (i > 0) {',
'                            result.v += ":";',
'                        }',
'                        result.v += model.getValue(rec, valProp);                        ',
'                    }',
'                } else {',
'                    rec = records[0];',
'                    if (dispProp) {',
'                        result.d = model.getValue(rec, dispProp);',
'                    }',
'                    result.v = model.getValue(rec, valProp);',
'                    if (extraCols) {',
'                        extraCols.forEach(function(p) {',
'                            result[p] = model.getValue(rec, p);',
'                        });',
'                    }',
'                }',
'                igDlg$[widget]("setValue", result )',
'                    [widget]("option", "valueConfirmed", true)',
'                    [widget]("close");',
'            } else {',
'                apex.message.alert("Make a selection.");',
'            }',
'        }',
'',
'        // Add set/getValue methods needed by Custom dialog plug-in.',
'        inst.dialogValue = "";',
'        inst.setValue = function(value) {',
'            this.dialogValue = value;',
'        };',
'        inst.getValue = function() {',
'            return this.dialogValue;',
'        };',
'',
'        igDlg$.on(widget + "open " + widget + "resize", function() {',
'            var h = igDlg$.find(".t-DialogRegion-bodyWrapperOut").height();',
'            // there is a inline style on the page to remove the padding if that wasn''t there',
'            // would need to subtract off the padding here',
'            ig$.height(h - 2);',
'        });',
'',
'        igDlg$.on(widget + "open", function() {',
'            var i, filters, rec,',
'                filterValue = "",',
'                view = ig$.interactiveGrid("getCurrentView"), // assume it will be grid view',
'                value = igDlg$[widget]("getValue"); // assume getValue returns a record id',
'',
'            // not sure this is needed',
'            // make sure the search field reflects the current filter',
'            filters = ig$.interactiveGrid("getFilters");',
'            for (i = 0; i < filters.length; i++) {',
'                if (filters[i].type === "row" ) {',
'                    filterValue = filters[i].value;',
'                    break;',
'                }',
'            }',
'            ig$.interactiveGrid("getToolbar").toolbar( "findElement", "search_field" ).val(filterValue);',
'',
'            // make initial selection',
'            // wait just a bit because if was invisible takes a moment to initialize the first time',
'            setTimeout(function() {',
'                rec = view.model.getRecord(value);',
'                // todo think about how this initial selection could be more robust; only delay if need to',
'                if (rec) {',
'                    view.view$.grid("setSelectedRecords", [rec]); // select',
'                } else {',
'                    ig$.interactiveGrid("focus");',
'                }',
'            }, 500);',
'        });',
'',
'        // Use IG activate to save',
'        ig$.on("gridactivatecell", function(event) {',
'            var recs,',
'                cell$ = $(event.target).closest(".a-GV-cell");',
'',
'            if ( (event.type === "keydown" && event.which !== $.ui.keyCode.ENTER) ||',
'                    cell$.hasClass("a-GV-selHeader") || cell$.hasClass("has-button") ) {',
'                return;',
'            }',
'            recs = ig$.interactiveGrid("getSelectedRecords");',
'            if ( recs.length > 0 ) {',
'                save();',
'            }',
'        }).on("keydown", "#" + igId + "_ig_toolbar_search_field", function(event) { // using delegated handling because toolbar can get refreshed',
'            if ( event.which === $.ui.keyCode.DOWN ) {',
'                ig$.interactiveGrid("getCurrentView").view$.grid("focus");',
'                event.preventDefault();',
'            }',
'        }).on("focusin", "#" + igId + "_ig_toolbar_search_field", function(event) { // using delegated handling because toolbar can get refreshed',
'            // want to select text on focus. Seems like this should be a common declarative option or even the default.',
'            ig$.interactiveGrid("getToolbar").toolbar( "findElement", "search_field" )[0].select();',
'        }).on("gridselectionchange", function(event) {',
'            var multi = ig$.interactiveGrid("getCurrentView").view$.grid("option", "multiple");',
'            // if !multiple selection and original event is click',
'            if (event.originalEvent && event.originalEvent.type === "click" && !multi) {',
'                recs = ig$.interactiveGrid("getSelectedRecords");',
'                if ( recs.length > 0 ) {',
'                    save();',
'                }',
'            }',
'        });',
'',
'        igDlg$.find(".do-save").click( save );',
'        igDlg$.find(".do-close").click(function() {',
'            igDlg$[widget]("close");',
'        });',
'    }',
'    app.initIGDialog = initIGDialog;',
'',
'})(app, apex.jQuery);',
''))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'//',
'// initialize dialogs used with custom popup',
'var inst, dlg$;',
'',
'// people IG with multiple outputs',
'app.initIGDialog("peoplePopup", "peoplePopup", "ID", "NAME", ["COUNTRY","GENDER"]);',
'',
'//',
'// expression dialog',
'dlg$ = $("#expressionDlg");',
'inst = dlg$.data("ui-dialog");',
'// Add set/getValue methods needed by Custom Popup plug-in.',
'inst.dialogValue = "";',
'inst.setValue = function(value) {',
'    $s("P530_EXPRESSION1", value);',
'};',
'inst.getValue = function() {',
'    return $v("P530_RESULT1");',
'};',
'function evalExpression() {',
'    var result,',
'        exp = $v("P530_EXPRESSION1");',
'    result = app.simpleEval(exp);',
'    if (result instanceof Error) {',
'        $s("P530_RESULT_DISP1", exp.trim().length > 0 ? result.message : "");',
'        $s("P530_RESULT1", "");',
'    } else {',
'        $s("P530_RESULT_DISP1", result);',
'        $s("P530_RESULT1", result);',
'    }',
'}',
'function save() {',
'    var theDlg$ = $("#expressionDlg");',
'    evalExpression();',
'    theDlg$.dialog("option", "valueConfirmed", true);',
'    apex.theme.closeRegion("expressionDlg");',
'}',
'$(apex.item("P530_EXPRESSION1").node).on("keypress", apex.util.debounce(function() {',
'    evalExpression();',
'}, 400)).on("keydown", function(event) {',
'    if (event.which === $.ui.keyCode.ENTER) {',
'        event.preventDefault();',
'        save();',
'    }',
'});',
'dlg$.find(".do-close").on("click", function() {',
'    apex.theme.closeRegion("expressionDlg");',
'});',
'dlg$.find(".do-save").on("click", save);',
'',
'//',
'// expression popup',
'dlg$ = $("#expressionPopup");',
'inst = dlg$.data("apex-popup");',
'// Add set/getValue methods needed by Custom Popup plug-in.',
'inst.dialogValue = "";',
'inst.setValue = function(value) {',
'    $s("P530_EXPRESSION2", value);',
'};',
'inst.getValue = function() {',
'    return $v("P530_RESULT2");',
'};',
'function evalExpression2() {',
'    var result,',
'        exp = $v("P530_EXPRESSION2");',
'    result = app.simpleEval(exp);',
'    if (result instanceof Error) {',
'        $s("P530_RESULT_DISP2", exp.trim().length > 0 ? result.message : "");',
'        $s("P530_RESULT2", "");',
'    } else {',
'        $s("P530_RESULT_DISP2", result);',
'        $s("P530_RESULT2", result);',
'    }',
'}',
'function save2() {',
'    var thePopup$ = $("#expressionPopup");',
'    evalExpression2();',
'    thePopup$.popup("option", "valueConfirmed", true);',
'    apex.theme.closeRegion("expressionPopup");',
'}',
'$(apex.item("P530_EXPRESSION2").node).on("keypress", apex.util.debounce(function() {',
'    evalExpression2();',
'}, 400)).on("keydown", function(event) {',
'    if (event.which === $.ui.keyCode.ENTER) {',
'        event.preventDefault();',
'        save2();',
'    }',
'});',
'dlg$.find(".do-close").on("click", function() {',
'    apex.theme.closeRegion("expressionPopup");',
'});',
'dlg$.find(".do-save").on("click", save);',
''))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.annotation {',
'    padding: 0 16px;',
'}',
'',
