wwv_flow_imp_page.create_page(
 p_id=>1000
,p_name=>'Tasks (reorder) - old'
,p_step_title=>'Tasks (reorder) - old'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// create a private scope where $ is set to apex.jQuery',
'(function($) {',
'    // do this after the page loads but before the IG is initialized to catch the initial events',
'    $(function() {',
'        //',
'        // This is the general pattern for adding to the grid view row or selection menus',
'        //',
'        // listen for view change events to find out when grid views are created ',
'        $("#tasks").on("interactivegridviewchange", function(event, data) {',
'            if ( data.view === "grid" && data.created ) {',
'                var items,',
'                    view = apex.region("tasks").widget().interactiveGrid("getViews", "grid"),',
'                    menu$ = view.selActionMenu$;',
'',
'                // now add items to the menu that reference actions added to the IG',
'                // see IG attribute Advanced JavaScript Code',
'                items = menu$.menu("option").items;',
'                items.push({',
'                    type:"separator"',
'                });',
'                items.push({',
'                    type:"action",',
'                    action: "selection-move-up"',
'                });',
'                items.push({',
'                    type:"action",',
'                    action: "selection-move-down"',
'                });',
'                items.push({',
'                    type:"action",',
'                    action: "selection-complete"',
'                });',
'            }',
'        });',
'',
'        // Reordering assumes that the client has all the data so call fetchAll',
'        // when the model is created.',
'        // Use with caution so that too much data isn''t loaded.',
'',
'        // the model gets released and created at various times such as when the report changes',
'        // listen for model created events so that we can subscribe to model notifications',
'        $("#tasks").on("interactivegridviewmodelcreate", function(event, ui) {',
'            var model = ui.model;',
'',
'            // Note this is only done for the grid veiw.',
'            if ( ui.viewId === "grid" ) {',
'                // Can remove if data will always be less than 50 records',
'                model.fetchAll(function() {});',
'            }',
'        });',
'',
'    });    ',
'})(apex.jQuery);',
''))
,p_page_template_options=>'#DEFAULT#'
,p_page_component_map=>'21'
);
