wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(8813264396561779825)
,p_event_id=>wwv_flow_imp.id(8813263916948779819)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var listName = $v("P1000_TASK_LIST");',
'var tasks = apex.region("tasks");',
'var model = tasks.widget().interactiveGrid("getViews").grid.model;',
'var prevListName = model.getOption("fields").LIST.defaultValue;',
'',
'// If there are changes prompt to save otherwise return to previous list',
'// Note something similar could be done when changing the Show Completed switch',
'if ( model.isChanged() ) {',
'    apex.message.confirm( "There are unsaved changes. Press OK to save them.", function( okPressed ) {',
'         $s("P1000_TASK_LIST", prevListName, null, true); // no change',
'         if( okPressed ) {',
'             tasks.widget().one("interactivegridsave", function() {',
'                 // change the list after the save',
'                 $s("P1000_TASK_LIST", listName);',
'             } );',
'             tasks.widget().interactiveGrid("getActions").invoke("save");',
'         }',
'    });',
'} else {',
'    // change the default value for LIST column for new records inserted',
'    model.getOption("fields").LIST.defaultValue = listName;',
'    // refresh the grid to get task records for this new list',
'    tasks.refresh();    ',
'}',
''))
);
