 p_id=>1001
,p_name=>'Copy Down (old)'
,p_step_title=>'Copy Down (old)'
,p_autocomplete_on_off=>'OFF'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.header-button.t-Button {',
'    margin: 0;',
'    background-color: transparent;',
'    box-shadow: none;',
'    border-radius: 0;',
'    min-width: 16px;',
'    padding: 8px 4px;',
'}',
'',
'.header-button.t-Button:focus,',
'.header-button.t-Button:hover',
'{',
'    background-color: rgba(0,0,0,.1);',
'}'))
,p_page_template_options=>'#DEFAULT#'
,p_page_component_map=>'21'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(34875414010143608366)
,p_plug_name=>'Notes'
,p_region_template_options=>'#DEFAULT#:js-useLocalStorage:is-collapsed:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(35108653483362181373)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>A few people have asked how to copy a value in a column down to fill in other values below it.',
'See this <a href=''https://community.oracle.com/thread/4019020'' target=''_blank''>thread</a> for example.',
'Select multiple rows and click the Copy Down button. The value in the corresponding',
'column of the first row is copied to all the rows in the selection.',
'The plan is to have built-in support for copy down in a future release of APEX.',
'</p>',
'<p>Demonstrates:<br>',
'Adding a button in a column header that invokes an action and defining a copy down action.',
'The action uses the model API to set the values. Because valuse are set in the model',
'dynamic actions and cascading LOVs do not run.',
'<br>Customizations:<br>',
'To add a button to the header see the column Heading attribute.',
'Whenever the Heading attribute has markup define the alternative label that gets shown in menus and dialogs.',
'Use column Advanced JavaScript Code to add the has-button class to the header cell.',
'See inline CSS for some styles for the heading buttons.',
'See IG Advanced JavaScript Code for the copy down action.',
'<br>Issues:<br>',
'Because the button in the header takes focus there is no way to open the header',
'popup menu with the keyboard; the mouse must be used.',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(37963572740939420649)
,p_plug_name=>'Copy Down (old)'
,p_region_name=>'emp'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(35108658789039181378)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select EMPNO,',
'       ENAME,',
'       JOB,',
'       MGR,',
'       HIREDATE,',
'       SAL,',
'       COMM,',
'       ONLEAVE,',
'       NOTES,',
'       DEPTNO,',
'       FLEX1,',
'       FLEX2,',
'       FLEX3,',
'       FLEX4,',
'       RATING',
'  from EBA_DEMO_IG_EMP'))
