prompt --application/deployment/definition
begin
wwv_flow_imp_shared.create_install(
 p_id=>wwv_flow_imp.id(31521218400650882051)
,p_deinstall_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'----------------------------------------------------------------',
'-- Remove Procedure',
'----------------------------------------------------------------',
'drop function striphtml;',
'',
'----------------------------------------------------------------',
'-- Remove Tables',
'---------------------------------------------------------------',
'drop table igcb_tasks    cascade constraints purge;',
'',
'----------------------------------------------------------------',
'-- Remove sequences',
'----------------------------------------------------------------',
'drop sequence igcb_tasks_seq;',
'  '))
,p_required_free_kb=>100
,p_required_sys_privs=>'CREATE PROCEDURE:CREATE TABLE:CREATE TRIGGER:CREATE VIEW'
);
end;
/
prompt --application/deployment/install/install_install
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(29465471139236602897)
,p_install_id=>wwv_flow_imp.id(31521218400650882051)
,p_name=>'install'
,p_sequence=>10
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'CREATE SEQUENCE IGCB_TASKS_SEQ MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 50 NOORDER  NOCYCLE;',
'',
'CREATE TABLE "IGCB_TASKS"',
'   (',
'    "ID" NUMBER,',
'    "LIST" VARCHAR2(60),',
'    "SEQ"  NUMBER,',
'    "TASK" VARCHAR2(120),',
'    "NAME" VARCHAR2(120),',
'    "DESCRIPTION" VARCHAR2(1000),',
'    "DONE" VARCHAR2(1) NOT NULL ENABLE,',
'    CONSTRAINT "IGCB_DONE_CK" CHECK (DONE in (''Y'', ''N'')) ENABLE,',
'    PRIMARY KEY ("ID")',
'  USING INDEX  ENABLE',
'   )',
'/',
'',
'CREATE INDEX IGCB_TASKS_LIST_IDX on IGCB_TASKS(LIST);',
'/',
'',
'CREATE OR REPLACE TRIGGER "BI_IGCB_TASKS"',
'    before insert on IGCB_TASKS',
'    for each row',
'    begin',
'      if :new.id is null then',
'          select igcb_tasks_seq.nextval into :new.id from sys.dual;',
'     end if;',
'    end;',
'/',
'ALTER TRIGGER "BI_IGCB_TASKS" ENABLE',
'/',
'',
'create or replace function striphtml(',
'    p_html in varchar2)',
'    return varchar2',
'is',
'    l_html varchar2(32767);',
'    l_pos pls_integer;',
'begin',
'    if length(p_html) > 0 then',
'        l_html := p_html;',
'        loop',
'            l_pos := regexp_instr(l_html, ''<[^<>]*>'');',
'            if l_pos > 0 then',
'                l_html := regexp_replace(l_html, ''<[^<>]*>'', null, l_pos);',
'            else',
'                exit;',
'            end if;',
'        end loop;',
'    end if;',
'',
'   return l_html;',
'end striphtml;',
''))
);
end;
/
prompt --application/deployment/checks
begin
wwv_flow_imp_shared.create_install_check(
 p_id=>wwv_flow_imp.id(4121575997053948922)
,p_install_id=>wwv_flow_imp.id(31521218400650882051)
,p_name=>'Check for sample data tables'
,p_sequence=>10
,p_check_type=>'FUNCTION_BODY'
,p_check_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  c number;',
'begin',
'  select count(*) into c from user_objects where object_type = ''TABLE'' and object_name in (',
'      ''EBA_DEMO_IG_EMP'', ''EBA_DEMO_IG_DEPT'' );',
'  return c = 2;',
'end;',
''))
,p_check_condition2=>'PLSQL'
,p_failure_message=>'This app relies on sample data provided in the Sample Interactive Grids app. Install that app from App Gallery first.'
);
end;
